import React, { useState } from 'react';
import Categories from './components/pages/Categories';
import BankAccounts from './components/pages/BankAccounts';
import Transactions from './components/pages/Transactions';
import Reports from './components/pages/Reports';
import { Menu, X, Landmark, List, CreditCard, PieChart, Wallet } from 'lucide-react';

type Page = 'Conta Bancária' | 'Categorias' | 'Conta Corrente' | 'Cartão de Crédito' | 'Relatórios';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<Page>('Relatórios');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const renderPage = () => {
    switch (activePage) {
      case 'Categorias':
        return <Categories />;
      case 'Conta Bancária':
        return <BankAccounts />;
      case 'Conta Corrente':
        return <Transactions transactionType="checking_account" title="Conta Corrente" />;
      case 'Cartão de Crédito':
        return <Transactions transactionType="credit_card" title="Cartão de Crédito" />;
      case 'Relatórios':
        return <Reports />;
      default:
        return <Reports />;
    }
  };

  const menuItems: { name: Page; icon: React.ReactNode }[] = [
    { name: 'Relatórios', icon: <PieChart className="w-5 h-5" /> },
    { name: 'Conta Bancária', icon: <Landmark className="w-5 h-5" /> },
    { name: 'Categorias', icon: <List className="w-5 h-5" /> },
    { name: 'Conta Corrente', icon: <Wallet className="w-5 h-5" /> },
    { name: 'Cartão de Crédito', icon: <CreditCard className="w-5 h-5" /> },
  ];

  const NavLink: React.FC<{ page: Page, icon: React.ReactNode }> = ({ page, icon }) => (
    <li key={page}>
      <a
        href="#"
        onClick={(e) => {
          e.preventDefault();
          setActivePage(page);
          setIsSidebarOpen(false);
        }}
        className={`flex items-center gap-3 p-3 rounded-lg transition-colors ${
          activePage === page
            ? 'bg-sky-600 text-white shadow-md'
            : 'text-slate-600 hover:bg-sky-100 hover:text-sky-700'
        }`}
      >
        {icon}
        <span className="font-medium">{page}</span>
      </a>
    </li>
  );

  return (
    <div className="flex h-screen bg-slate-100">
      {/* Sidebar */}
      <aside
        className={`bg-white border-r border-slate-200 w-64 min-h-screen p-4 flex flex-col transition-transform duration-300 ease-in-out fixed lg:relative lg:translate-x-0 ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
        } z-20`}
      >
        <div className="flex items-center gap-2 pb-4 border-b border-slate-200">
          <div className="bg-sky-600 p-2 rounded-lg">
            <Landmark className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-xl font-bold text-slate-800">Curatela Contas</h1>
        </div>
        <nav className="mt-6 flex-1">
          <ul className="space-y-2">
            {menuItems.map(item => <NavLink key={item.name} page={item.name} icon={item.icon} />)}
          </ul>
        </nav>
        <div className="text-center text-xs text-slate-400 mt-6">
          <p>Feito com cuidado para você.</p>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white/80 backdrop-blur-lg shadow-sm p-4 flex items-center justify-between lg:hidden sticky top-0 z-10">
          <div className="flex items-center gap-2">
            <div className="bg-sky-600 p-2 rounded-lg">
              <Landmark className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-lg font-bold text-slate-800">Curatela Contas</h1>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2">
            {isSidebarOpen ? <X className="w-6 h-6 text-slate-700" /> : <Menu className="w-6 h-6 text-slate-700" />}
          </button>
        </header>
        <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
          {renderPage()}
        </main>
      </div>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/40 z-10 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}
    </div>
  );
};

export default App;

export enum CategoryType {
  RECEITA = 'RECEITA',
  DESPESA = 'DESPESA',
}

export interface Category {
  id: string;
  name: string;
  type: CategoryType;
}

export enum AccountType {
  CONTA_CORRENTE = 'Conta Corrente',
  CONTA_POUPANCA = 'Conta Poupança',
}

export interface BankAccount {
  id: string;
  name: string;
  type: AccountType;
  initialBalance: number;
}

export enum TransactionNature {
  RECEITA = 'RECEITA',
  DESPESA = 'DESPESA',
}

export interface Transaction {
  id: string;
  description: string; // Not in spec, but good to have. Let's use category name if not provided.
  nature: TransactionNature;
  accountId: string;
  categoryId: string;
  date: string; // ISO format
  value: number;
  type: 'checking_account' | 'credit_card';
}

import React, { createContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { BankAccount, Category, Transaction } from '../types';

interface AppContextType {
  accounts: BankAccount[];
  addAccount: (account: Omit<BankAccount, 'id'>) => void;
  updateAccount: (account: BankAccount) => void;
  deleteAccount: (id: string) => void;
  getAccountById: (id: string) => BankAccount | undefined;

  categories: Category[];
  addCategory: (category: Omit<Category, 'id'>) => void;
  updateCategory: (category: Category) => void;
  deleteCategory: (id: string) => void;

  transactions: Transaction[];
  addTransaction: (transaction: Omit<Transaction, 'id'>) => void;
  updateTransaction: (transaction: Transaction) => void;
  deleteTransaction: (id: string) => void;

  calculateCurrentBalance: (accountId: string) => number;
}

export const AppContext = createContext<AppContextType | undefined>(undefined);

const usePersistentState = <T,>(key: string, defaultValue: T): [T, React.Dispatch<React.SetStateAction<T>>] => {
  const [state, setState] = useState<T>(() => {
    try {
      const storedValue = localStorage.getItem(key);
      return storedValue ? JSON.parse(storedValue) : defaultValue;
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error);
      return defaultValue;
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(state));
    } catch (error) {
      console.error(`Error setting localStorage key "${key}":`, error);
    }
  }, [key, state]);

  return [state, setState];
};

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [accounts, setAccounts] = usePersistentState<BankAccount[]>('accounts', []);
  const [categories, setCategories] = usePersistentState<Category[]>('categories', []);
  const [transactions, setTransactions] = usePersistentState<Transaction[]>('transactions', []);

  // Accounts CRUD
  const addAccount = (account: Omit<BankAccount, 'id'>) => {
    setAccounts(prev => [...prev, { ...account, id: crypto.randomUUID() }]);
  };
  const updateAccount = (updatedAccount: BankAccount) => {
    setAccounts(prev => prev.map(acc => acc.id === updatedAccount.id ? updatedAccount : acc));
  };
  const deleteAccount = (id: string) => {
    setAccounts(prev => prev.filter(acc => acc.id !== id));
    setTransactions(prev => prev.filter(t => t.accountId !== id));
  };
  const getAccountById = (id: string) => accounts.find(acc => acc.id === id);

  // Categories CRUD
  const addCategory = (category: Omit<Category, 'id'>) => {
    setCategories(prev => [...prev, { ...category, id: crypto.randomUUID() }]);
  };
  const updateCategory = (updatedCategory: Category) => {
    setCategories(prev => prev.map(cat => cat.id === updatedCategory.id ? updatedCategory : cat));
  };
  const deleteCategory = (id: string) => {
    setCategories(prev => prev.filter(cat => cat.id !== id));
    setTransactions(prev => prev.filter(t => t.categoryId !== id));
  };

  // Transactions CRUD
  const addTransaction = (transaction: Omit<Transaction, 'id'>) => {
    setTransactions(prev => [...prev, { ...transaction, id: crypto.randomUUID() }].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const updateTransaction = (updatedTransaction: Transaction) => {
    setTransactions(prev => prev.map(t => t.id === updatedTransaction.id ? updatedTransaction : t).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const calculateCurrentBalance = useMemo(() => (accountId: string): number => {
      const account = accounts.find(acc => acc.id === accountId);
      if (!account) return 0;

      const accountTransactions = transactions.filter(t => t.accountId === accountId && t.type === 'checking_account');

      const balance = accountTransactions.reduce((acc, curr) => {
          if (curr.nature === 'RECEITA') {
              return acc + curr.value;
          }
          return acc - curr.value;
      }, account.initialBalance);

      return balance;
  }, [accounts, transactions]);


  const contextValue = {
    accounts, addAccount, updateAccount, deleteAccount, getAccountById,
    categories, addCategory, updateCategory, deleteCategory,
    transactions, addTransaction, updateTransaction, deleteTransaction,
    calculateCurrentBalance
  };

  return (
    <AppContext.Provider value={contextValue}>
      {children}
    </AppContext.Provider>
  );
};

import { useContext } from 'react';
import { AppContext } from '../context/AppContext';

export const useAppData = () => {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useAppData must be used within an AppProvider');
  }
  return context;
};

export const formatCurrency = (value: number): string => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
};

export const formatCurrencyInput = (value: string): string => {
  let numericValue = value.replace(/\D/g, '');
  if (!numericValue) return '';

  numericValue = (parseInt(numericValue, 10) / 100).toFixed(2);

  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(parseFloat(numericValue));
};

export const unformatCurrency = (value: string): number => {
    const numericValue = value.replace(/\D/g, '');
    if (!numericValue) return 0;
    return parseInt(numericValue, 10) / 100;
};

export const formatDate = (dateString: string): string => {
  return new Date(dateString).toLocaleDateString('pt-BR', { timeZone: 'UTC' });
};

import { Transaction, Category, BankAccount } from '../types';
import { formatCurrency, formatDate } from './formatters';

declare global {
    interface Window {
        jspdf: any;
    }
}

export const generateTransactionsPDF = (
    transactions: Transaction[],
    categories: Category[],
    accounts: BankAccount[],
    title: string
) => {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'landscape' });

    doc.setFontSize(18);
    doc.text(`Relatório de Lançamentos - ${title}`, 14, 22);
    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Gerado em: ${new Date().toLocaleDateString('pt-BR')} ${new Date().toLocaleTimeString('pt-BR')}`, 14, 29);

    const tableColumn = ["Data", "Descrição", "Conta", "Natureza", "Valor"];
    const tableRows: (string | number)[][] = [];

    const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'N/A';
    const getAccountName = (id: string) => accounts.find(a => a.id === id)?.name || 'N/A';

    transactions.forEach(t => {
        const transactionData = [
            formatDate(t.date),
            getCategoryName(t.categoryId),
            getAccountName(t.accountId),
            t.nature,
            formatCurrency(t.value)
        ];
        tableRows.push(transactionData);
    });

    let totalReceitas = 0;
    let totalDespesas = 0;
    transactions.forEach(t => {
        if (t.nature === 'RECEITA') totalReceitas += t.value;
        else totalDespesas += t.value;
    });
    const saldo = totalReceitas - totalDespesas;

    doc.autoTable({
        head: [tableColumn],
        body: tableRows,
        startY: 35,
        theme: 'grid',
        headStyles: { fillColor: [22, 163, 74] },
        didDrawPage: (data: any) => {
            // Footer
            const pageCount = doc.internal.getNumberOfPages();
            doc.setFontSize(10);
            doc.text(`Página ${data.pageNumber} de ${pageCount}`, data.settings.margin.left, doc.internal.pageSize.height - 10);
        }
    });

    const finalY = doc.lastAutoTable.finalY + 10;
    doc.setFontSize(12);
    doc.text('Resumo do Período', 14, finalY);
    doc.setFontSize(10);
    doc.text(`Total de Receitas: ${formatCurrency(totalReceitas)}`, 14, finalY + 7);
    doc.text(`Total de Despesas: ${formatCurrency(totalDespesas)}`, 14, finalY + 14);
    doc.setFontSize(11);
    doc.setFont(undefined, 'bold');
    doc.text(`Saldo do Período: ${formatCurrency(saldo)}`, 14, finalY + 21);


    doc.save(`relatorio_${title.toLowerCase().replace(' ', '_')}_${new Date().toISOString().slice(0,10)}.pdf`);
};

import React, { ReactNode } from 'react';
