import { UploadCloud, ScanLine, AlertCircle, Loader2 } from 'lucide-react';

// FIX: API key is now handled via environment variables as per guidelines.

interface ScannedData {
  value: number;
  date: string;
  description: string;
  scannedImage: string;
}

