    value: number;
    nature: TransactionNature;
    categoryId: string;
    categoryName: string;
    status: ParsedStatus;
    message?: string;
}

const normalizeHeader = (str: string): string => str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const StatusBadge: React.FC<{ status: ParsedStatus }> = ({ status }) => {
    const config = {
        new: { Icon: BadgeCheck, text: 'Novo', color: 'text-green-600 bg-green-100' },
