                        const date = new Date(Date.UTC(year, month, day));

                        // Validate if the created date is what we expect (e.g., handles 32/02/2024)
                        if (date.getUTCFullYear() === year && date.getUTCMonth() === month && date.getUTCDate() === day) {
                            parsedDate = date;
                        }
                    }
                }

                if (parsedDate) {
                    // We have a valid Date object, now convert it to 'YYYY-MM-DD' string for storage
                    result.date = parsedDate.toISOString().split('T')[0];
                } else {
                    result.status = 'invalid';
                    result.message = 'Data inválida. Use DD/MM/AAAA ou formate a célula como Data.';
                }

                // Validate Value - More robust parsing for different currency formats
                let numValue: number;
                if (typeof valueVal === 'number') {
                    numValue = valueVal;
                } else if (typeof valueVal === 'string') {
                    const s = String(valueVal).trim();
                    if (s.includes(',')) {
                        // Contains a comma, assume pt-BR format like "1.234,56"
                        numValue = parseFloat(s.replace(/\./g, '').replace(',', '.'));
                    } else {
                        // No comma, assume format like "1234.56" or "1,234.56"
                        // Here we only remove commas, treating dots as potential decimal separators.
                        numValue = parseFloat(s.replace(/,/g, ''));
                    }
                } else {
                    numValue = NaN;
                }

                if (typeof numValue === 'number' && !isNaN(numValue) && numValue !== 0) {
                    result.value = Math.abs(numValue);
                    result.nature = TransactionNature.DESPESA; // Nature is always expense for credit card import
                } else {
                    result.status = 'invalid';
                    result.message = (result.message || '') + ' Valor inválido.';
                }

                // Validate Category
                const category = categoryMap.get(categoryVal.toLowerCase());
                if (category) {
                    if (category.type === CategoryType.DESPESA) {
                        result.categoryId = category.id;
                    } else {
                        result.status = 'invalid';
                        result.message = (result.message || '') + ` Categoria '${categoryVal}' é do tipo Receita.`;
                    }
                } else {
                    result.status = 'invalid';
                    result.message = (result.message || '') + ` Categoria '${categoryVal}' não encontrada.`;
                }
                processed.push(result as ParsedTransaction);
            }
            setParsedTransactions(processed);
        } catch (err) {
            console.error("Erro ao processar o arquivo:", err);
            setError(err instanceof Error ? err.message : "Ocorreu um erro desconhecido.");
            setFile(null);
        } finally {
            setIsLoading(false);
        }
    }, [categories]);

    const handleImport = async () => {
        const transactionsToImport = parsedTransactions
            .filter(t => t.status === 'new')
            .map(({ status, message, categoryName, ...rest }) => ({
                ...rest,
                accountId: selectedAccountId,
                type: transactionType
            }));

        if (transactionsToImport.length === 0) {
            setError('Nenhum lançamento novo para importar.');
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            await addTransactionsBatch(transactionsToImport);
            alert(`${transactionsToImport.length} lançamentos importados com sucesso!`);
            handleClose();
        } catch (err) {
            setError('Falha ao importar lançamentos.');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    const transactionsToImportCount = useMemo(() => {
        return parsedTransactions.filter(t => t.status === 'new').length;
    }, [parsedTransactions]);

    return (
