declare global {
    interface Window {
        XLSX: any;
    }
}

type ParsedStatus = 'new' | 'invalid';
interface ParsedTransaction {
    date: string;
    description: string;
    value: number;
    nature: TransactionNature;
    categoryId: string;
    categoryName: string;
    status: ParsedStatus;
    message?: string;
}

const normalizeHeader = (str: string): string => str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

const StatusBadge: React.FC<{ status: ParsedStatus }> = ({ status }) => {
    const config = {
        new: { Icon: BadgeCheck, text: 'Novo', color: 'text-green-600 bg-green-100' },
        invalid: { Icon: BadgeX, text: 'Inválido', color: 'text-red-600 bg-red-100' },
    }[status];
    return (
        <span className={`flex items-center gap-1.5 text-xs font-medium px-2.5 py-1 rounded-full ${config.color}`}>
            <config.Icon size={14} />
            {config.text}
        </span>
    );
};

const TransactionImportModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    transactionType: 'checking_account' | 'credit_card';
}> = ({ isOpen, onClose, transactionType }) => {
    const { accounts, categories, addTransactionsBatch } = useAppData();
    const [file, setFile] = useState<File | null>(null);
    const [parsedTransactions, setParsedTransactions] = useState<ParsedTransaction[]>([]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [progress, setProgress] = useState(0);

    const resetState = useCallback(() => {
        setFile(null);
        setParsedTransactions([]);
        // Don't reset selectedAccountId
        setIsLoading(false);
        setError(null);
        setProgress(0);
    }, []);

    const handleClose = useCallback(() => {
        resetState();
        setSelectedAccountId('');
        onClose();
    }, [resetState, onClose]);

    const handleFileSelect = useCallback(async (selectedFile: File) => {
        if (!selectedFile) return;
        setIsLoading(true);
        setError(null);
        setParsedTransactions([]);
        setFile(selectedFile);
        setProgress(0);

        try {
            const data = await selectedFile.arrayBuffer();
            const workbook = window.XLSX.read(data, { type: 'buffer' });
            const sheetName = workbook.SheetNames[0];
            const worksheet = workbook.Sheets[sheetName];
            const json: any[][] = window.XLSX.utils.sheet_to_json(worksheet, { header: 1, raw: false, cellDates: true });

            if (json.length < 2) throw new Error('A planilha está vazia.');

            const headerRow = json[0].map(h => normalizeHeader(String(h)));
            const requiredHeaders = ['data', 'descricao', 'categoria', 'valor'];
            const headerIndices: { [key: string]: number } = {};

            requiredHeaders.forEach(reqHeader => {
                const index = headerRow.findIndex(h => h === reqHeader);
                if(index === -1) throw new Error(`Coluna obrigatória "${reqHeader}" não encontrada na planilha.`);
                headerIndices[reqHeader] = index;
            });

            const categoryMap = new Map(categories.map(c => [c.name.toLowerCase(), c]));
            const processed: ParsedTransaction[] = [];
            const rows = json.slice(1);
            const totalRows = rows.length;

            for (let i = 0; i < totalRows; i++) {
                const row = rows[i];
                if(row.every(cell => cell === null || cell === undefined || cell === '')) continue; // Skip empty rows

                const dateVal = row[headerIndices.data];
                const valueVal = row[headerIndices.valor];
                const categoryVal = String(row[headerIndices.categoria] || '').trim();
                const descriptionVal = String(row[headerIndices.descricao] || '').trim();

                const result: Partial<ParsedTransaction> & { categoryName: string } = {
                    status: 'new',
                    description: descriptionVal,
                    categoryName: categoryVal,
                };

                // Validate Date - Robust Parsing
                let parsedDate: Date | null = null;
                // 1. Handle valid Date objects from sheetjs
                if (dateVal instanceof Date && !isNaN(dateVal.getTime())) {
                    parsedDate = dateVal;
                } 
                // 2. Handle numeric Excel dates
                else if (typeof dateVal === 'number') {
                    // Excel's epoch starts on 1899-12-30. The number of days between that and Unix epoch is 25569.
                    // We create a date in UTC to avoid timezone issues.
                    const date = new Date(Math.round((dateVal - 25569) * 86400 * 1000));
                    if (!isNaN(date.getTime())) {
                        parsedDate = date;
                    }
                }
                // 3. Handle string dates in DD/MM/AAAA format
                else if (typeof dateVal === 'string') {
                    const trimmedDateVal = dateVal.trim();
                    const parts = trimmedDateVal.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
                    if (parts) {
                        // parts[1] = DD, parts[2] = MM, parts[3] = AAAA
                        const day = parseInt(parts[1], 10);
                        const month = parseInt(parts[2], 10) - 1; // JS months are 0-indexed
                        const year = parseInt(parts[3], 10);

                        // Create date in UTC to avoid local timezone from shifting the date
                        const date = new Date(Date.UTC(year, month, day));

                        // Validate if the created date is what we expect (e.g., handles 32/02/2024)
                        if (date.getUTCFullYear() === year && date.getUTCMonth() === month && date.getUTCDate() === day) {
                            parsedDate = date;
                        }
                    }
                }

                if (parsedDate) {
                    // We have a valid Date object, now convert it to 'YYYY-MM-DD' string for storage
                    result.date = parsedDate.toISOString().split('T')[0];
                } else {
                    result.status = 'invalid';
                    result.message = 'Data inválida. Use DD/MM/AAAA ou formate a célula como Data.';
                }

                // Validate Value - More robust parsing for different currency formats
                let numValue: number;
                if (typeof valueVal === 'number') {
                    numValue = valueVal;
                } else if (typeof valueVal === 'string') {
                    const s = String(valueVal).trim();
                    if (s.includes(',')) {
                        // Contains a comma, assume pt-BR format like "1.234,56"
                        numValue = parseFloat(s.replace(/\./g, '').replace(',', '.'));
                    } else {
                        // No comma, assume format like "1234.56" or "1,234.56"
                        // Here we only remove commas, treating dots as potential decimal separators.
                        numValue = parseFloat(s.replace(/,/g, ''));
                    }
                } else {
                    numValue = NaN;
                }

                if (typeof numValue === 'number' && !isNaN(numValue) && numValue !== 0) {
                    result.value = Math.abs(numValue);
                    result.nature = TransactionNature.DESPESA; // Nature is always expense for credit card import
                } else {
                    result.status = 'invalid';
                    result.message = (result.message || '') + ' Valor inválido.';
                }

                // Validate Category
                const category = categoryMap.get(categoryVal.toLowerCase());
                if (category) {
                    if (category.type === CategoryType.DESPESA) {
                        result.categoryId = category.id;
                    } else {
                        result.status = 'invalid';
                        result.message = (result.message || '') + ` Categoria '${categoryVal}' é do tipo Receita.`;
                    }
                } else {
                    result.status = 'invalid';
                    result.message = (result.message || '') + ` Categoria '${categoryVal}' não encontrada.`;
                }
                processed.push(result as ParsedTransaction);

                const currentProgress = Math.round(((i + 1) / totalRows) * 100);
                setProgress(currentProgress);
                if (i % 20 === 0 || i === totalRows - 1) {
                    await new Promise(resolve => setTimeout(resolve, 0));
                }
            }
            setParsedTransactions(processed);
        } catch (err) {
            console.error("Erro ao processar o arquivo:", err);
            setError(err instanceof Error ? err.message : "Ocorreu um erro desconhecido.");
            setFile(null);
        } finally {
            setIsLoading(false);
        }
    }, [categories]);

    const handleImport = async () => {
        const transactionsToImport = parsedTransactions
            .filter(t => t.status === 'new')
            .map(({ status, message, categoryName, ...rest }) => ({
                ...rest,
                accountId: selectedAccountId,
                type: transactionType
            }));

        if (transactionsToImport.length === 0) {
            setError('Nenhum lançamento novo para importar.');
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            await addTransactionsBatch(transactionsToImport);
            alert(`${transactionsToImport.length} lançamentos importados com sucesso!`);
            handleClose();
        } catch (err) {
            setError('Falha ao importar lançamentos.');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    const transactionsToImportCount = useMemo(() => {
        return parsedTransactions.filter(t => t.status === 'new').length;
    }, [parsedTransactions]);

    return (
        <Modal isOpen={isOpen} onClose={handleClose} title="Importar Lançamentos de Planilha XLS">
