                    } else if (s.includes('.')) {
                        // No comma, but dot(s) exist. This is ambiguous (e.g., "1.234" vs "11.29").
                        // Heuristic: If the last dot is followed by 1 or 2 digits, it's a decimal point.
                        const lastDotIndex = s.lastIndexOf('.');
                        const digitsAfterLastDot = s.length - 1 - lastDotIndex;

                        if (digitsAfterLastDot > 0 && digitsAfterLastDot <= 2) {
                            // Assumed decimal, e.g., "11.29" or "1.234.56".
                            // Remove all other dots (as thousands) and keep the last one.
                            const firstPart = s.substring(0, lastDotIndex).replace(/\./g, '');
                            const secondPart = s.substring(lastDotIndex + 1);
                            standardized = `${firstPart}.${secondPart}`;
                        } else {
                            // Assumed thousands, e.g., "1.234" or "12.345". Remove all dots.
                            standardized = s.replace(/\./g, '');
                        }
                    } else {
                        // No comma, no dot. e.g., "1234"
                        standardized = s;
                    }

                    numValue = parseFloat(standardized);
                }

                if (typeof numValue === 'number' && !isNaN(numValue) && numValue !== 0) {
                    result.value = Math.abs(numValue);
                    result.nature = TransactionNature.DESPESA; // Nature is always expense for credit card import
                } else {
                    result.status = 'invalid';
                    result.message = (result.message || '') + ' Valor inválido.';
                }

                // Validate Category
                const category = categoryMap.get(categoryVal.toLowerCase());
                if (category) {
                    if (category.type === CategoryType.DESPESA) {
                        result.categoryId = category.id;
                    } else {
                        result.status = 'invalid';
                        result.message = (result.message || '') + ` Categoria '${categoryVal}' é do tipo Receita.`;
                    }
                } else {
                    result.status = 'invalid';
                    result.message = (result.message || '') + ` Categoria '${categoryVal}' não encontrada.`;
                }
                processed.push(result as ParsedTransaction);

                const currentProgress = Math.round(((i + 1) / totalRows) * 100);
                setProgress(currentProgress);
                if (i % 20 === 0 || i === totalRows - 1) {
                    await new Promise(resolve => setTimeout(resolve, 0));
                }
            }
            setParsedTransactions(processed);
        } catch (err) {
            console.error("Erro ao processar o arquivo:", err);
            setError(err instanceof Error ? err.message : "Ocorreu um erro desconhecido.");
            setFile(null);
        } finally {
            setIsLoading(false);
        }
    }, [categories]);

    const handleImport = async () => {
        const transactionsToImport = parsedTransactions
            .filter(t => t.status === 'new')
            .map(({ status, message, categoryName, ...rest }) => ({
                ...rest,
                accountId: selectedAccountId,
