import React, { useState, useCallback } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import Modal from '../ui/Modal';
import { fileToBase64 } from '../../utils/imageUtils';
import { useLogger } from '../../hooks/useLogger';
import { GEMINI_API_KEY } from '../../supabase/client';
import { UploadCloud, ScanLine, AlertCircle, Loader2 } from 'lucide-react';

interface ScannedData {
  value: number;
  date: string;
  description: string;
  scannedImage: string;
}

interface ReceiptScannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onScanComplete: (data: ScannedData) => void;
}

const ReceiptScannerModal: React.FC<ReceiptScannerModalProps> = ({ isOpen, onClose, onScanComplete }) => {
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [scanError, setScanError] = useState('');
  const log = useLogger();

  const resetState = () => {
    setSelectedFile(null);
    setPreviewUrl(null);
    setIsLoading(false);
    setScanError('');
  }

  const handleClose = () => {
    resetState();
    onClose();
  }

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      setScanError('');
      setSelectedFile(file);
      setPreviewUrl(URL.createObjectURL(file));
    }
  };

  const onDrop = useCallback((event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      setScanError('');
      setSelectedFile(file);
      setPreviewUrl(URL.createObjectURL(file));
    } else {
        setScanError('Por favor, envie um arquivo de imagem (PNG, JPG, etc).')
    }
  }, []);

  const onDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleScan = async () => {
    if (!selectedFile) {
      setScanError('Por favor, selecione uma imagem primeiro.');
      return;
    }
    setIsLoading(true);
    setScanError('');

    log.info('Iniciando digitalização do recibo...');
    try {
      // FIX: Corrected the placeholder string in the comparison to match the constant value from supabase/client.ts, resolving the type error.
      if (!GEMINI_API_KEY || GEMINI_API_KEY === "AIzaSyAsjrqN8VIYVr9z37vEHXw5YJEj4orX-Ok") {
        log.error("A chave de API do Gemini não foi configurada no arquivo supabase/client.ts.");
        throw new Error("API_KEY_NOT_CONFIGURED");
      }

      log.info('Comprimindo e convertendo imagem para base64...');
      const { mimeType, data: base64Image } = await fileToBase64(selectedFile);
      log.info('Imagem processada. Enviando para a IA...');

      const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

      const imagePart = {
        inlineData: {
          mimeType,
          data: base64Image,
        },
      };

      // --- Chamadas sequenciais para a IA para maior compatibilidade ---
      log.info('Iniciando chamadas sequenciais para a IA para maior compatibilidade (Safari).');

      // 1. Extrair dados
      log.info('Executando extração de dados...');
      const dataPrompt = `Analise a imagem do recibo e extraia o valor total da transação (use ponto como separador decimal), a data (no formato AAAA-MM-DD) e o nome do estabelecimento ou uma breve descrição da compra. Se a data não for encontrada, use a data de hoje. Se o valor não for encontrado, use 0.`;
      const dataResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [{ text: dataPrompt }, imagePart] },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              value: { type: Type.NUMBER, description: 'Valor total da compra, use ponto como separador decimal.' },
              date: { type: Type.STRING, description: 'Data da transação no formato AAAA-MM-DD.' },
              description: { type: Type.STRING, description: 'Nome do estabelecimento ou descrição da compra.' },
            },
            required: ["value", "date", "description"]
          }
        }
      });
      log.info('Extração de dados concluída.');

      // 2. Limpar a imagem
      log.info('Executando limpeza da imagem...');
      const cleaningPrompt = `Aja como um scanner de documentos profissional e realize um pós-processamento completo na imagem deste recibo. O objetivo é gerar um documento limpo, nítido e perfeitamente legível, ideal para arquivamento e prestação de contas. Execute as seguintes ações:
1. **Detecção e Alinhamento:** Detecte as bordas do documento, corrija a perspectiva e qualquer ângulo torto, e centralize o recibo na imagem.
2. **Limpeza de Fundo:** Remova completamente o fundo original, substituindo-o por um fundo perfeitamente branco e uniforme.
3. **Ajuste de Qualidade:** Aumente o contraste e a nitidez para garantir que o texto seja escuro e totalmente legível.
4. **Remoção de Imperfeições:** Elimine quaisquer sombras, reflexos, borrões ou outras distorções visuais.
O resultado final deve ser idêntico a um documento digitalizado por um scanner de alta qualidade.`;
      const imageResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: cleaningPrompt }, imagePart] }
      });
      log.info('Limpeza da imagem concluída. Ambas as respostas da IA foram recebidas.');

      // Processando os resultados
      if (!dataResponse.text) {
        throw new Error("A IA não retornou dados de texto para extração.");
      }
      const extractedData = JSON.parse(dataResponse.text.trim());
      log.info('Dados extraídos:', extractedData);

      const imagePartResponse = imageResponse.candidates?.[0]?.content?.parts?.find(part => part.inlineData);
      let cleanedImageBase64: string;
      if (imagePartResponse?.inlineData?.data) {
        cleanedImageBase64 = imagePartResponse.inlineData.data;
        log.info('Imagem limpa e processada.');
      } else {
        cleanedImageBase64 = base64Image;
        log.warn('Não foi possível obter imagem limpa da IA, usando a original otimizada.');
      }

      // Validando e combinando os dados
      if (!/^\d{4}-\d{2}-\d{2}$/.test(extractedData.date)) {
        log.warn("Formato de data inválido da IA, usando data de hoje.", { date: extractedData.date });
        extractedData.date = new Date().toISOString().split('T')[0];
      }

      const finalData = {
        ...extractedData,
        scannedImage: cleanedImageBase64,
      };

      log.info('Digitalização concluída com sucesso.', { description: finalData.description, value: finalData.value, date: finalData.date });
      onScanComplete(finalData);
      handleClose();

    } catch (error) {
      log.error("Ocorreu um erro detalhado ao digitalizar o recibo", { error });

      let userMessage = 'A IA não conseguiu processar a imagem. Verifique o console para detalhes técnicos e tente novamente.';
      if (error instanceof Error) {
        if (error.message === "API_KEY_NOT_CONFIGURED") {
          userMessage = "Atenção: A chave de API do Gemini precisa ser configurada no arquivo supabase/client.ts.";
        } else if (error.message.includes('JSON')) {
          userMessage = 'A IA retornou um formato inválido. Tente uma imagem mais nítida.';
        } else if (error.message.toLowerCase().includes('api key')) {
          userMessage = 'Erro de autenticação com a API. Verifique se a chave de API está correta e tente novamente.';
        } else {
          const specificError = (error as any).cause?.toString() || error.toString();
          userMessage = `Falha na comunicação com a IA. Detalhes: ${specificError}.`;
        }
      }
      setScanError(userMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Digitalizar Recibo com IA">
      <div className="space-y-4">
        {previewUrl ? (
          <div className="text-center">
            <img src={previewUrl} alt="Pré-visualização do recibo" className="max-h-48 w-auto inline-block rounded-md border" />
          </div>
        ) : (
          <div
            onDrop={onDrop}
            onDragOver={onDragOver}
            className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-colors"
            onClick={() => document.getElementById('file-upload')?.click()}
          >
            <UploadCloud className="mx-auto h-12 w-12 text-gray-400" />
            <p className="mt-2 text-sm text-gray-600">Arraste e solte o recibo aqui, ou clique para selecionar</p>
            <p className="text-xs text-gray-500">PNG, JPG ou WEBP</p>
            <input id="file-upload" type="file" accept="image/*" className="hidden" onChange={handleFileChange} />
          </div>
        )}

        {scanError && (
          <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-3 rounded-md flex items-center gap-2">
            <AlertCircle size={20} />
            <p className="text-sm">{scanError}</p>
          </div>
        )}

        <div className="flex justify-end gap-3 pt-4">
            <button
                type="button"
                onClick={handleClose}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
                disabled={isLoading}
            >
                Cancelar
            </button>
            <button
                type="button"
                onClick={handleScan}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors font-semibold shadow disabled:bg-blue-300 disabled:cursor-not-allowed"
                disabled={!selectedFile || isLoading}
            >
                {isLoading ? (
                    <>
                        <Loader2 size={20} className="animate-spin" />
                        Analisando...
                    </>
                ) : (
                    <>
                        <ScanLine size={20} />
                        Analisar Recibo
                    </>
                )}
            </button>
        </div>
      </div>
    </Modal>
  );
};

export default ReceiptScannerModal;

import React, { useState } from 'react';
import Categories from './components/pages/Categories';
import BankAccounts from './components/pages/BankAccounts';
import Transactions from './components/pages/Transactions';
import Reports from './components/pages/Reports';
import Documents from './components/pages/Documents';
import Console from './components/ui/Console';
import SettingsModal from './components/ui/SettingsModal';
import { useAppData } from './hooks/useAppData';
import { Menu, X, Landmark, List, CreditCard, LayoutDashboard, Wallet, HeartPulse, Loader2, FileText, Cog } from 'lucide-react';

type Page = 'Dashboard' | 'Conta Bancária' | 'Categorias' | 'Conta Corrente' | 'Cartão de Crédito' | 'Documentos';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<Page>('Dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const { isLoading } = useAppData();

  if (isLoading) {
    return (
      <div className="flex h-screen items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="w-12 h-12 text-blue-600 animate-spin mx-auto" />
          <p className="mt-4 text-lg font-semibold text-gray-600">Carregando dados...</p>
        </div>
      </div>
    );
  }

  const renderPage = () => {
    switch (activePage) {
      case 'Categorias':
        return <Categories />;
      case 'Conta Bancária':
        return <BankAccounts />;
      case 'Conta Corrente':
        return <Transactions transactionType="checking_account" title="Conta Corrente" />;
      case 'Cartão de Crédito':
        return <Transactions transactionType="credit_card" title="Cartão de Crédito" />;
      case 'Dashboard':
        return <Reports />;
      case 'Documentos':
        return <Documents />;
      default:
        return <Reports />;
    }
  };

  const menuItems: { name: Page; icon: React.ReactNode }[] = [
    { name: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
    { name: 'Conta Corrente', icon: <Wallet className="w-5 h-5" /> },
    { name: 'Cartão de Crédito', icon: <CreditCard className="w-5 h-5" /> },
    { name: 'Documentos', icon: <FileText className="w-5 h-5" /> },
    { name: 'Conta Bancária', icon: <Landmark className="w-5 h-5" /> },
    { name: 'Categorias', icon: <List className="w-5 h-5" /> },
  ];

  const NavLink: React.FC<{ page: Page, icon: React.ReactNode }> = ({ page, icon }) => (
    <li key={page}>
      <a
        href="#"
        onClick={(e) => {
          e.preventDefault();
          setActivePage(page);
          setIsSidebarOpen(false);
        }}
        className={`flex items-center gap-3 p-3 rounded-lg transition-colors font-medium ${
          activePage === page
            ? 'bg-blue-600 text-white shadow'
            : 'text-gray-600 hover:bg-blue-50 hover:text-blue-600'
        }`}
      >
        {icon}
        <span>{page}</span>
      </a>
    </li>
  );

  return (
    <div className="flex h-screen bg-gray-50">
      {/* Sidebar */}
      <aside
        className={`bg-white w-64 min-h-screen p-4 flex flex-col transition-transform duration-300 ease-in-out fixed lg:relative lg:translate-x-0 z-20 shadow-lg lg:shadow-none ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        <div className="flex items-center gap-3 pb-4 border-b border-gray-100">
          <div className="bg-blue-600 p-2 rounded-lg">
            <HeartPulse className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-xl font-bold text-gray-800">Curatela Contas</h1>
        </div>
        <nav className="mt-6 flex-1">
          <ul className="space-y-2">
            {menuItems.map(item => <NavLink key={item.name} page={item.name} icon={item.icon} />)}
          </ul>
        </nav>

        <div className="border-t border-gray-100 pt-4 mt-auto">
          <button 
              onClick={() => {
                setIsSettingsModalOpen(true);
                setIsSidebarOpen(false);
              }}
              className="flex w-full items-center gap-3 p-3 rounded-lg text-gray-600 hover:bg-blue-50 hover:text-blue-600 transition-colors font-medium mb-2"
          >
              <Cog className="w-5 h-5" />
              <span>Configurações</span>
          </button>
          <div className="text-center text-xs text-gray-400 pt-2">
            <p>Feito com cuidado para você.</p>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white/80 backdrop-blur-lg border-b border-gray-100 p-4 flex items-center justify-between lg:hidden sticky top-0 z-10">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <HeartPulse className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-lg font-bold text-gray-800">Curatela Contas</h1>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2">
            {isSidebarOpen ? <X className="w-6 h-6 text-gray-700" /> : <Menu className="w-6 h-6 text-gray-700" />}
          </button>
        </header>
        <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
          {renderPage()}
        </main>
      </div>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/40 z-10 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      {/* Modals */}
      <Console />
      <SettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} />
    </div>
  );
};

export default App;

