import React, { useState, useCallback } from 'react';
import Modal from '../ui/Modal';
import { fileToBase64 } from '../../utils/imageUtils';
import { useLogger } from '../../hooks/useLogger';
import { supabase } from '../../supabase/client';
import { UploadCloud, ScanLine, AlertCircle, Loader2 } from 'lucide-react';

interface ScannedData {
  value: number;
  date: string;
  description: string;
  scannedImage: string;
}

interface ReceiptScannerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onScanComplete: (data: ScannedData) => void;
}

const ReceiptScannerModal: React.FC<ReceiptScannerModalProps> = ({ isOpen, onClose, onScanComplete }) => {
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [scanError, setScanError] = useState('');
  const log = useLogger();

  const resetState = () => {
    setSelectedFile(null);
    setPreviewUrl(null);
    setIsLoading(false);
    setScanError('');
  }

  const handleClose = () => {
    resetState();
    onClose();
  }

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      setScanError('');
      setSelectedFile(file);
      setPreviewUrl(URL.createObjectURL(file));
    }
  };

  const onDrop = useCallback((event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      setScanError('');
      setSelectedFile(file);
      setPreviewUrl(URL.createObjectURL(file));
    } else {
        setScanError('Por favor, envie um arquivo de imagem (PNG, JPG, etc).')
    }
  }, []);

  const onDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleScan = async () => {
    if (!selectedFile) {
      setScanError('Por favor, selecione uma imagem primeiro.');
      return;
    }

    setIsLoading(true);
    setScanError('');
    log.info('Iniciando digitalização segura via Edge Function...');

    try {
      const { mimeType, data: base64Image } = await fileToBase64(selectedFile);
      log.info('Imagem processada. Invocando a função "scan-receipt"...');

      const { data, error } = await supabase.functions.invoke('scan-receipt', {
        body: { mimeType, image: base64Image },
      });

      if (error) {
        throw new Error(`Function error: ${error.message}`);
      }

      // Otimização: Verificação mais flexível que aceita valor 0 e confia nos padrões do backend.
      if (data.value == null || !data.date || !data.scannedImage) {
        log.error("Resposta da Edge Function incompleta:", data);
        throw new Error(data.error || 'A IA não conseguiu extrair todos os dados necessários do recibo.');
      }

      onScanComplete(data);
      handleClose();

    } catch (error) {
      log.error("Erro detalhado na digitalização:", error);
      const userMessage = error instanceof Error ? error.message : 'Falha ao processar o recibo. Verifique a qualidade da imagem e tente novamente.';
      setScanError(userMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Digitalizar Recibo com IA">
      <div className="space-y-4">
        {previewUrl ? (
          <div className="text-center">
            <img src={previewUrl} alt="Pré-visualização" className="max-h-48 w-auto inline-block rounded-md border" />
          </div>
        ) : (
          <div
            onDrop={onDrop}
            onDragOver={onDragOver}
            className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-colors"
            onClick={() => document.getElementById('file-upload')?.click()}
          >
            <UploadCloud className="mx-auto h-12 w-12 text-gray-400" />
            <p className="mt-2 text-sm text-gray-600">Arraste ou selecione o recibo</p>
            <input id="file-upload" type="file" accept="image/*" className="hidden" onChange={handleFileChange} />
          </div>
        )}

        {scanError && (
          <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-3 rounded-md flex items-center gap-2">
            <AlertCircle size={20} />
            <p className="text-sm">{scanError}</p>
          </div>
        )}

        <div className="flex justify-end gap-3 pt-4">
            <button onClick={handleClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md">Cancelar</button>
            <button
                onClick={handleScan}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 font-semibold shadow disabled:bg-blue-300"
                disabled={!selectedFile || isLoading}
            >
                {isLoading ? <Loader2 size={20} className="animate-spin" /> : <ScanLine size={20} />}
                {isLoading ? 'IA está analisando...' : 'Analisar Recibo'}
            </button>
        </div>
      </div>
    </Modal>
  );
};

export default ReceiptScannerModal;

// NOTA: Este arquivo deve estar em `supabase/functions/scan-receipt/index.ts`
import { GoogleGenAI } from "https://esm.sh/@google/genai@0.12.0";

// FIX: Declare Deno to resolve TypeScript errors in environments that don't have Deno types.
declare const Deno: any;

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// Pega a chave de API das variáveis de ambiente secretas do Supabase
const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY");

Deno.serve(async (req) => {
  // Trata a requisição pre-flight do CORS
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    if (!GEMINI_API_KEY) {
        throw new Error("PARA O DESENVOLVEDOR: A variável de ambiente GEMINI_API_KEY não está configurada nas Edge Functions do Supabase.");
    }

    const { mimeType, image } = await req.json();
    if (!mimeType || !image) {
        return new Response(JSON.stringify({ error: "mimeType e image são obrigatórios." }), {
            status: 400,
            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        });
    }

    const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });
    const imagePart = { inlineData: { mimeType, data: image } };

    // Chamadas paralelas para a IA para otimizar o tempo de resposta
    const dataPromise = ai.models.generateContent({
      model: 'gemini-flash-lite-latest',
      contents: { parts: [
        { text: `Extraia o valor total (número com ponto decimal), a data (formato AAAA-MM-DD) e uma breve descrição deste recibo. Tente extrair o máximo de informação possível. Se um campo não for encontrado, use um valor padrão: para 'value', use 0; para 'date', use a data de hoje; para 'description', use 'Recibo Digitalizado'. Responda SOMENTE com um objeto JSON: {"value": number, "date": "string", "description": "string"}. Não use markdown.` },
        imagePart
      ]},
    });

    const imagePromise = ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [
        { text: `Aja como um scanner profissional. Otimize esta imagem de recibo para arquivamento digital, melhorando contraste, brilho e nitidez.` },
        imagePart
      ]}
    });

    const [dataResponse, imageResponse] = await Promise.all([dataPromise, imagePromise]);

    if (!dataResponse.text) {
      throw new Error("A IA não retornou dados de texto para extração.");
    }

    let extractedData = { value: 0, date: '', description: 'Recibo Digitalizado' };
    try {
        const parsedJson = JSON.parse(dataResponse.text.trim());
        extractedData = { ...extractedData, ...parsedJson };
    } catch (e) {
        console.error("JSON.parse falhou, usando valores padrão. Erro:", e);
    }

    // Sanitiza e valida os dados finais
    if (typeof extractedData.value !== 'number' || isNaN(extractedData.value)) {
        extractedData.value = 0;
    }
    if (typeof extractedData.description !== 'string' || !extractedData.description.trim()) {
        extractedData.description = 'Recibo Digitalizado';
    }
    if (typeof extractedData.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(extractedData.date)) {
      extractedData.date = new Date().toISOString().split('T')[0];
    }

    const imagePartResponse = imageResponse.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
    const cleanedImageBase64 = imagePartResponse?.inlineData?.data || image;

    const responsePayload = { ...extractedData, scannedImage: cleanedImageBase64 };

    return new Response(JSON.stringify(responsePayload), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 200,
    });

  } catch (error) {
    console.error("Erro na Edge Function 'scan-receipt':", error);
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500,
    });
  }
});

