import AIChat from './components/ai/AIChat';
import { useAppData } from './hooks/useAppData';
import { Menu, X, Landmark, List, CreditCard, LayoutDashboard, Wallet, HeartPulse, Loader2, FileText, Heartbeat } from 'lucide-react';

type Page = 'Dashboard' | 'Conta Bancária' | 'Categorias' | 'Conta Corrente' | 'Cartão de Crédito' | 'Documentos' | 'Funcionamento';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<Page>('Dashboard');
