        }`}
      >
        {icon}
        <span>{page}</span>
      </a>
    </li>
  );

  return (
    <div className="flex h-screen bg-gray-50">
      {/* Sidebar */}
      <aside
        className={`bg-white w-64 min-h-screen p-4 flex flex-col transition-transform duration-300 ease-in-out fixed lg:relative lg:translate-x-0 z-20 shadow-lg lg:shadow-none ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        <div className="flex items-center gap-3 pb-4 border-b border-gray-100">
          <div className="bg-blue-600 p-2 rounded-lg">
            <HeartPulse className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-xl font-bold text-gray-800">Curatela Contas</h1>
        </div>
        <nav className="mt-6 flex-1">
          <ul className="space-y-2">
            {menuItems.map(item => <NavLink key={item.name} page={item.name} icon={item.icon} />)}
          </ul>
        </nav>

        <div className="border-t border-gray-100 pt-4 mt-auto text-center text-xs text-gray-400">
            <p>Feito com cuidado para você.</p>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white/80 backdrop-blur-lg border-b border-gray-100 p-4 flex items-center justify-between lg:hidden sticky top-0 z-10">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <HeartPulse className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-lg font-bold text-gray-800">Curatela Contas</h1>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2">
            {isSidebarOpen ? <X className="w-6 h-6 text-gray-700" /> : <Menu className="w-6 h-6 text-gray-700" />}
          </button>
        </header>
        <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
          {renderPage()}
        </main>
      </div>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/40 z-10 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      {/* Modals & Global Components */}
      <Console />
      <AIChat />
    </div>
  );
};

export default App;

import React from 'react';
import { useAppData } from '../../hooks/useAppData';
import { Heartbeat, Server } from 'lucide-react';

const formatLogDate = (dateString: string): string => {
  return new Date(dateString).toLocaleString('pt-BR', {
    dateStyle: 'long',
    timeStyle: 'medium',
  });
};

const Funcionamento: React.FC = () => {
  const { keepAliveLogs } = useAppData();

  return (
    <div className="space-y-8">
      <div className="flex items-center gap-4">
        <div className="bg-green-100 p-3 rounded-full">
            <Heartbeat className="w-8 h-8 text-green-600" />
        </div>
        <div>
            <h1 className="text-3xl font-bold text-gray-800">Status de Funcionamento</h1>
            <p className="text-gray-500 mt-1">Este registro mostra a atividade diária para manter o banco de dados ativo.</p>
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm">
        <h2 className="text-lg font-semibold text-gray-700 mb-4">Histórico de Atividade</h2>
        {keepAliveLogs.length === 0 ? (
          <div className="text-center py-16">
            <Server className="mx-auto h-12 w-12 text-gray-300" />
            <p className="text-gray-500 mt-4">Nenhum registro de atividade encontrado.</p>
            <p className="text-gray-400 text-sm mt-1">A primeira verificação automática deve ocorrer em breve.</p>
          </div>
        ) : (
          <div className="flow-root">
            <ul role="list" className="-mb-8">
              {keepAliveLogs.map((log, logIdx) => (
                <li key={log.id}>
                  <div className="relative pb-8">
                    {logIdx !== keepAliveLogs.length - 1 ? (
                      <span className="absolute left-4 top-4 -ml-px h-full w-0.5 bg-gray-200" aria-hidden="true" />
                    ) : null}
                    <div className="relative flex space-x-3 items-center">
                      <div>
                        <span className="h-8 w-8 rounded-full bg-green-500 flex items-center justify-center ring-8 ring-white">
                          <Heartbeat className="h-5 w-5 text-white" />
                        </span>
                      </div>
                      <div className="flex min-w-0 flex-1 justify-between space-x-4">
                        <div>
                          <p className="text-sm text-gray-700">
                            Verificação de atividade do sistema executada com sucesso.
                          </p>
                        </div>
                        <div className="whitespace-nowrap text-right text-sm text-gray-500">
                          <time dateTime={log.pinged_at}>{formatLogDate(log.pinged_at)}</time>
                        </div>
                      </div>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default Funcionamento;

// NOTA: Este arquivo deve estar em `supabase/functions/keep-alive/index.ts`
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

// FIX: Declare Deno to resolve TypeScript errors in environments that don't have Deno types.
declare const Deno: any;

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// A função será invocada via cron job, que pode precisar de uma chave de serviço
// para contornar políticas de Row Level Security.
const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
      throw new Error("PARA O DESENVOLVEDOR: As variáveis de ambiente SUPABASE_URL e SUPABASE_SERVICE_ROLE_KEY precisam ser configuradas para esta função.");
    }

    // Cria um cliente Supabase com a chave de serviço para privilégios de administrador
    const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Insere um novo registro na tabela keep_alive_logs.
    // A tabela deve ter um valor padrão para 'pinged_at' como now().
    const { error } = await supabaseAdmin.from('keep_alive_logs').insert({});

    if (error) {
      throw error;
    }

    return new Response(JSON.stringify({ success: true, message: "Verificação de atividade bem-sucedida." }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 200,
    });

  } catch (error) {
    console.error("Erro na Edge Function 'keep-alive':", error);
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500,
    });
  }
});

