        const end = new Date(endDate);
        start.setUTCHours(0,0,0,0);
        end.setUTCHours(23,59,59,999);

        const transactionsInPeriod = transactions.filter(t => {
            const tDate = new Date(t.date);
            return t.accountId === accountId && tDate >= start && tDate <= end && t.type === transactionType;
        });

        generateTransactionsPDF({
            account,
            period: { start: startDate, end: endDate },
            transactionsInPeriod,
            allTransactions: transactions,
            transactionType,
            title
        });
        setIsPdfModalOpen(false);
    };

    const handleScanComplete = (data: ScannedData) => {
      const newAttachment: NewAttachment = {
        id: crypto.randomUUID(),
        name: `Recibo_${data.date}.jpg`,
        type: 'image_base64_jpeg',
        data: data.scannedImage,
      };

      const despesaCategory = categories.find(c => c.type === CategoryType.DESPESA);

      setTransactionToEdit({
        description: data.description,
        value: data.value,
        date: data.date,
        nature: TransactionNature.DESPESA,
        categoryId: despesaCategory?.id || '',
        attachments: [newAttachment] as any, // Transient state
      });
      setIsScannerOpen(false);
      setIsModalOpen(true);
    };

    const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'N/A';
    const getAccountName = (id: string) => accounts.find(a => a.id === id)?.name || 'N/A';

    return (
         <div className="space-y-8">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800">{title}</h1>
                    <p className="text-gray-500 mt-1">Registre e gerencie suas movimentações financeiras.</p>
                </div>
                <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
                    {transactionType === 'credit_card' && (
                        <button onClick={() => setIsImportModalOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors font-semibold shadow-sm">
                            <Upload size={18} />
                            Importar XLS
                        </button>
                    )}
                    <button onClick={() => setIsPdfModalOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors font-semibold shadow-sm">
                        <Download size={18} />
                        Gerar PDF
                    </button>
                    <button onClick={() => setIsScannerOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-semibold shadow">
                        <ScanLine size={20} />
                        Digitalizar com IA
                    </button>
                    <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-semibold shadow">
                        <Plus size={20} />
                        Lançamento
                    </button>
                </div>
            </div>

            <div className="bg-white p-4 rounded-2xl shadow-sm">
                <div className="flex items-center gap-2 mb-4">
                    <Filter size={18} className="text-gray-500" />
                    <h3 className="font-semibold text-gray-600">Filtros</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                    <input type="date" value={filterDate} onChange={e => setFilterDate(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300" />
                    <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <option value="">Todas as categorias</option>
                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                    <select value={filterNature} onChange={e => setFilterNature(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <option value="">Toda natureza</option>
                        <option value="RECEITA">Receita</option>
                        <option value="DESPESA">Despesa</option>
                    </select>
                </div>
            </div>

            <div className="bg-white p-4 sm:p-6 rounded-2xl shadow-sm">
                {filteredTransactions.length === 0 ? (
                    <div className="text-center py-16">
                        <Wallet className="mx-auto h-12 w-12 text-gray-300" />
                        <p className="text-gray-500 mt-4">Nenhum lançamento encontrado.</p>
                        <p className="text-gray-400 text-sm mt-1">{transactions.length > 0 ? "Ajuste os filtros ou adicione um novo lançamento." : 'Clique em "Criar Lançamento" para começar.'}</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b-2 border-gray-100">
                                <tr>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider">Descrição</th>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider hidden md:table-cell">Conta</th>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider text-right">Valor</th>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider text-right">Ações</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredTransactions.map(t => (
                                    <tr key={t.id} onClick={() => handleOpenModal(t)} className="border-b border-gray-100 last:border-b-0 hover:bg-gray-50/50 transition-colors cursor-pointer">
                                        <td className="p-4">
                                            <div className="font-medium text-gray-800 flex items-center gap-2">
                                              {t.attachments && t.attachments.length > 0 && 
                                                <button onClick={(e) => { e.stopPropagation(); setViewingAttachment(t.attachments![0]); }} title="Ver anexo">
                                                  <Paperclip className="w-4 h-4 text-blue-500 hover:text-blue-700" />
                                                </button>
                                              }
                                              <span>{t.description || getCategoryName(t.categoryId)}</span>
                                            </div>
                                            <div className="text-xs text-gray-500 ml-6">{formatDate(t.date)} - {getCategoryName(t.categoryId)}</div>
                                        </td>
                                        <td className="p-4 text-gray-600 hidden md:table-cell">{getAccountName(t.accountId)}</td>
                                        <td className={`p-4 font-semibold text-right ${t.nature === 'RECEITA' ? 'text-green-600' : 'text-red-600'}`}>{formatCurrency(t.value)}</td>
                                        <td className="p-4">
                                            <div className="flex justify-end">
                                                <button 
                                                    onClick={(e) => { e.stopPropagation(); handleDelete(t.id); }} 
                                                    className="p-2 text-gray-400 hover:text-red-600 rounded-full transition-colors"
                                                    title="Excluir lançamento"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            <PdfOptionsModal
                isOpen={isPdfModalOpen}
                onClose={() => setIsPdfModalOpen(false)}
                onSubmit={handleGeneratePdf}
            />

            <Modal isOpen={isModalOpen} onClose={handleCloseModal} title={transactionToEdit && 'id' in transactionToEdit ? 'Editar Lançamento' : 'Novo Lançamento'}>
                <TransactionForm onSubmit={handleSubmit} onClose={handleCloseModal} transactionToEdit={transactionToEdit} transactionType={transactionType} />
            </Modal>

            <ReceiptScannerModal
                isOpen={isScannerOpen}
                onClose={() => setIsScannerOpen(false)}
                onScanComplete={handleScanComplete}
            />

            <TransactionImportModal
                isOpen={isImportModalOpen}
                onClose={() => setIsImportModalOpen(false)}
                transactionType={transactionType}
            />

            {viewingAttachment && (
              <ViewAttachmentModal
                  isOpen={!!viewingAttachment}
                  onClose={() => setViewingAttachment(null)}
                  attachment={viewingAttachment}
              />
            )}
        </div>
    );
};

export default Transactions;

import React, { useState, useMemo, useEffect } from 'react';
import { useAppData } from '../../hooks/useAppData';
import { Transaction, TransactionNature, CategoryType, Attachment, NewAttachment } from '../../types';
import Modal from '../ui/Modal';
import PdfOptionsModal from '../ui/PdfOptionsModal';
import ReceiptScannerModal from '../ai/ReceiptScannerModal';
import TransactionImportModal from '../ui/TransactionImportModal';
import ViewAttachmentModal from '../ui/ViewAttachmentModal';
import CurrencyInput from '../ui/CurrencyInput';
import { formatCurrency, formatDate } from '../../utils/formatters';
import { generateTransactionsPDF } from '../../utils/pdfGenerator';
import { Plus, Trash2, Download, Filter, Wallet, ScanLine, Paperclip, Upload, ArrowRight, Edit } from 'lucide-react';

interface ScannedData {
  value: number;
  date: string;
  description: string;
  scannedImage: string;
}

const TransactionForm: React.FC<{
  onSubmit: (transaction: Omit<Transaction, 'id'>, newAttachments: NewAttachment[]) => Promise<void>;
  onClose: () => void;
  transactionToEdit?: Partial<Transaction> | null;
  transactionType: 'checking_account' | 'credit_card';
}> = ({ onSubmit, onClose, transactionToEdit, transactionType }) => {
    const { accounts, categories } = useAppData();
    const [nature, setNature] = useState<TransactionNature>(transactionToEdit?.nature || TransactionNature.DESPESA);
    const [description, setDescription] = useState(transactionToEdit?.description || '');
    const [accountId, setAccountId] = useState(transactionToEdit?.accountId || '');
    const [categoryId, setCategoryId] = useState(transactionToEdit?.categoryId || '');
    const [date, setDate] = useState(transactionToEdit?.date ? transactionToEdit.date.split('T')[0] : new Date().toISOString().split('T')[0]);
    const [value, setValue] = useState(transactionToEdit?.value || 0);
    const [newAttachment, setNewAttachment] = useState<NewAttachment | null>(null);
    const [errors, setErrors] = useState<{ [key: string]: string }>({});
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [step, setStep] = useState(1);
    const [isDateInputFocused, setIsDateInputFocused] = useState(false);

    const isScannedFlow = useMemo(() => {
      // FIX: Cast to 'unknown' first to resolve unsafe type conversion error.
      return !!(transactionToEdit?.attachments?.[0] as unknown as NewAttachment)?.data;
    }, [transactionToEdit]);

    useEffect(() => {
        setStep(1); // Reset step on modal open/change
        if (transactionToEdit) {
            setNature(transactionToEdit.nature || TransactionNature.DESPESA);
            setDescription(transactionToEdit.description || '');
            setAccountId(transactionToEdit.accountId || '');
            setCategoryId(transactionToEdit.categoryId || '');
            setDate(transactionToEdit.date ? transactionToEdit.date.split('T')[0] : new Date().toISOString().split('T')[0]);
            setValue(transactionToEdit.value || 0);

            // FIX: Cast to 'unknown' first to resolve unsafe type conversion error.
            const potentialNewAttachment = transactionToEdit.attachments?.[0] as unknown as NewAttachment | undefined;
            setNewAttachment(potentialNewAttachment?.data ? potentialNewAttachment : null);

        } else { // Reset for new manual transaction
            setNature(TransactionNature.DESPESA);
            setDescription('');
            setAccountId('');
            setCategoryId('');
            setDate(new Date().toISOString().split('T')[0]);
            setValue(0);
            setNewAttachment(null);
        }
    }, [transactionToEdit]);

    const filteredCategories = useMemo(() => {
        return categories.filter(c => c.type === (nature as unknown as CategoryType));
    }, [categories, nature]);

    const validate = () => {
        const newErrors: { [key: string]: string } = {};
        if (!accountId) newErrors.accountId = 'Selecione uma conta.';
        if (!categoryId) newErrors.categoryId = 'Selecione uma categoria.';
        if (value <= 0) newErrors.value = 'O valor deve ser maior que zero.';
        if (!date) newErrors.date = 'A data é obrigatória.';
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleNext = (e: React.MouseEvent<HTMLButtonElement>) => {
        e.preventDefault();
        if (validate()) {
            setStep(2);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validate()) return;
        setIsSubmitting(true);
        const transactionData = { description, nature, accountId, categoryId, date, value, type: transactionType };
        await onSubmit(transactionData, newAttachment ? [newAttachment] : []);
        setIsSubmitting(false);
    };

    const formFields = (
      <div className="space-y-3">
        <div>
            <label className="block text-sm font-medium text-gray-600 mb-2">Natureza do Lançamento</label>
            <div className="grid grid-cols-2 gap-4">
                <button type="button" onClick={() => { setNature(TransactionNature.RECEITA); setCategoryId(''); }} className={`p-2 rounded-lg font-semibold transition ${nature === TransactionNature.RECEITA ? 'bg-green-500 text-white ring-2 ring-green-600 ring-offset-2' : 'bg-gray-100 hover:bg-green-100'}`}>Receita</button>
                <button type="button" onClick={() => { setNature(TransactionNature.DESPESA); setCategoryId(''); }} className={`p-2 rounded-lg font-semibold transition ${nature === TransactionNature.DESPESA ? 'bg-red-500 text-white ring-2 ring-red-600 ring-offset-2' : 'bg-gray-100 hover:bg-red-100'}`}>Despesa</button>
            </div>
        </div>

        <div>
            <label htmlFor="description" className="block text-sm font-medium text-gray-600">Descrição</label>
            <input
                type="text"
                id="description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="mt-1 w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Ex: Compras do mês"
            />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
                <label htmlFor="accountId" className="block text-sm font-medium text-gray-600">Conta Bancária</label>
                <select id="accountId" value={accountId} onChange={(e) => setAccountId(e.target.value)} className={`mt-1 w-full px-3 py-2 border ${errors.accountId ? 'border-red-500' : 'border-gray-300'} bg-white rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}>
                    <option value="">Selecione...</option>
                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                </select>
            </div>
            <div>
                <label htmlFor="categoryId" className="block text-sm font-medium text-gray-600">Categoria</label>
                <select id="categoryId" value={categoryId} onChange={(e) => setCategoryId(e.target.value)} className={`mt-1 w-full px-3 py-2 border ${errors.categoryId ? 'border-red-500' : 'border-gray-300'} bg-white rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}>
                    <option value="">Selecione...</option>
                    {filteredCategories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>
            </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
                <label htmlFor="date" className="block text-sm font-medium text-gray-600">Data</label>
                <input
                    type={isDateInputFocused ? 'date' : 'text'}
                    id="date"
                    value={isDateInputFocused ? date : (date ? formatDate(date) : '')}
                    onFocus={() => setIsDateInputFocused(true)}
                    onBlur={() => setIsDateInputFocused(false)}
                    onChange={(e) => setDate(e.target.value)}
                    className={`mt-1 w-full px-3 py-2 border ${errors.date ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}
                />
            </div>
            <div>
                <label htmlFor="value" className="block text-sm font-medium text-gray-600">Valor</label>
                <CurrencyInput id="value" value={value} onChange={setValue} />
                {errors.value && <p className="text-sm text-red-500 mt-1">{errors.value}</p>}
            </div>
        </div>
      </div>
    );

    return (
        <form onSubmit={handleSubmit}>
            {isScannedFlow ? (
                // Multi-step flow for scanned receipts
                <div className="space-y-4">
                    {step === 1 && (
                        formFields
                    )}
                    {step === 2 && (
                         <div className="space-y-4">
                            <p className="text-center text-gray-600">Por favor, confirme o anexo para salvar.</p>
                            {newAttachment && (
                                <div className="relative group">
                                    <p className="text-sm font-medium text-gray-600 mb-1">Recibo Digitalizado</p>
                                    <img
                                        src={`data:image/jpeg;base64,${newAttachment.data}`}
                                        alt="Recibo digitalizado"
                                        className="rounded-lg border p-1 max-h-60 w-auto mx-auto"
                                    />
                                </div>
                            )}
                        </div>
                    )}
                </div>
            ) : (
                // Single-step for manual entry/edit
                formFields
            )}

            <div className="flex justify-end gap-3 pt-4 mt-4 border-t border-gray-100">
                {isScannedFlow && step === 2 && (
                    <button type="button" onClick={() => setStep(1)} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors">Voltar</button>
                )}
                <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors">Cancelar</button>
                {isScannedFlow && step === 1 ? (
                    <button type="button" onClick={handleNext} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors font-semibold shadow">
                        Próximo <ArrowRight size={16} />
                    </button>
                ) : (
                    <button type="submit" disabled={isSubmitting} className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors font-semibold shadow disabled:bg-blue-300">
                        {isSubmitting ? 'Salvando...' : 'Confirmar'}
                    </button>
                )}
            </div>
        </form>
    );
};


const Transactions: React.FC<{ transactionType: 'checking_account' | 'credit_card', title: string }> = ({ transactionType, title }) => {
    const { transactions, categories, accounts, addTransaction, updateTransaction, deleteTransaction, getAccountById } = useAppData();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isActionModalOpen, setIsActionModalOpen] = useState(false);
    const [isPdfModalOpen, setIsPdfModalOpen] = useState(false);
    const [isScannerOpen, setIsScannerOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [transactionToEdit, setTransactionToEdit] = useState<Partial<Transaction> | null>(null);
    const [viewingAttachment, setViewingAttachment] = useState<Attachment | null>(null);

    const [filterDate, setFilterDate] = useState('');
    const [filterCategory, setFilterCategory] = useState('');
    const [filterNature, setFilterNature] = useState('');

    const filteredTransactions = useMemo(() => {
        return transactions
            .filter(t => t.type === transactionType)
            .filter(t => !filterDate || t.date.startsWith(filterDate))
            .filter(t => !filterCategory || t.categoryId === filterCategory)
            .filter(t => !filterNature || t.nature === filterNature);
    }, [transactions, transactionType, filterDate, filterCategory, filterNature]);

    const handleOpenModal = (transaction?: Transaction) => {
        setTransactionToEdit(transaction || null);
        setIsModalOpen(true);
    };

    const handleRowClick = (transaction: Transaction) => {
        setTransactionToEdit(transaction);
        setIsActionModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setTransactionToEdit(null);
    };

    const handleCloseActionModal = () => {
        setIsActionModalOpen(false);
        setTransactionToEdit(null);
    };

    const handleSubmit = async (data: Omit<Transaction, 'id'>, newAttachments: NewAttachment[]) => {
        if (transactionToEdit && 'id' in transactionToEdit) {
            await updateTransaction({ ...transactionToEdit, ...data } as Transaction, newAttachments);
        } else {
            await addTransaction(data, newAttachments);
        }
        handleCloseModal();
    };

    const handleDelete = async (id: string) => {
        if(window.confirm('Tem certeza que deseja remover este lançamento? O anexo também será removido permanentemente.')) {
            await deleteTransaction(id);
        }
    };

    const handleGeneratePdf = ({ accountId, startDate, endDate }: { accountId: string, startDate: string, endDate: string }) => {
        const account = getAccountById(accountId);
        if (!account) return;

        const start = new Date(startDate);
        const end = new Date(endDate);
        start.setUTCHours(0,0,0,0);
        end.setUTCHours(23,59,59,999);

        const transactionsInPeriod = transactions.filter(t => {
            const tDate = new Date(t.date);
            return t.accountId === accountId && tDate >= start && tDate <= end && t.type === transactionType;
        });

        generateTransactionsPDF({
            account,
            period: { start: startDate, end: endDate },
            transactionsInPeriod,
            allTransactions: transactions,
            transactionType,
            title
        });
        setIsPdfModalOpen(false);
    };

    const handleScanComplete = (data: ScannedData) => {
      const newAttachment: NewAttachment = {
        id: crypto.randomUUID(),
        name: `Recibo_${data.date}.jpg`,
        type: 'image_base64_jpeg',
        data: data.scannedImage,
      };

      const despesaCategory = categories.find(c => c.type === CategoryType.DESPESA);

      setTransactionToEdit({
        description: data.description,
        value: data.value,
        date: data.date,
        nature: TransactionNature.DESPESA,
        categoryId: despesaCategory?.id || '',
        attachments: [newAttachment] as any, // Transient state
      });
      setIsScannerOpen(false);
      setIsModalOpen(true);
    };

    const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'N/A';
    const getAccountName = (id: string) => accounts.find(a => a.id === id)?.name || 'N/A';

    return (
         <div className="space-y-8">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800">{title}</h1>
                    <p className="text-gray-500 mt-1">Registre e gerencie suas movimentações financeiras.</p>
                </div>
                <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
                    {transactionType === 'credit_card' && (
                        <button onClick={() => setIsImportModalOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors font-semibold shadow-sm">
                            <Upload size={18} />
                            Importar XLS
                        </button>
                    )}
                    <button onClick={() => setIsPdfModalOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors font-semibold shadow-sm">
                        <Download size={18} />
                        Gerar PDF
                    </button>
                    <button onClick={() => setIsScannerOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-semibold shadow">
                        <ScanLine size={20} />
                        Digitalizar com IA
                    </button>
                    <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-semibold shadow">
                        <Plus size={20} />
                        Lançamento
                    </button>
                </div>
            </div>

            <div className="bg-white p-4 rounded-2xl shadow-sm">
                <div className="flex items-center gap-2 mb-4">
                    <Filter size={18} className="text-gray-500" />
                    <h3 className="font-semibold text-gray-600">Filtros</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                    <input type="date" value={filterDate} onChange={e => setFilterDate(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300" />
                    <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <option value="">Todas as categorias</option>
                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                    <select value={filterNature} onChange={e => setFilterNature(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <option value="">Toda natureza</option>
                        <option value="RECEITA">Receita</option>
                        <option value="DESPESA">Despesa</option>
                    </select>
                </div>
            </div>

            <div className="bg-white p-4 sm:p-6 rounded-2xl shadow-sm">
                {filteredTransactions.length === 0 ? (
                    <div className="text-center py-16">
                        <Wallet className="mx-auto h-12 w-12 text-gray-300" />
                        <p className="text-gray-500 mt-4">Nenhum lançamento encontrado.</p>
                        <p className="text-gray-400 text-sm mt-1">{transactions.length > 0 ? "Ajuste os filtros ou adicione um novo lançamento." : 'Clique em "Criar Lançamento" para começar.'}</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b-2 border-gray-100">
                                <tr>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider">Descrição</th>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider hidden md:table-cell">Conta</th>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider text-right">Valor</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredTransactions.map(t => (
                                    <tr key={t.id} onClick={() => handleRowClick(t)} className="border-b border-gray-100 last:border-b-0 hover:bg-gray-50/50 transition-colors cursor-pointer">
                                        <td className="p-4">
                                            <div className="font-medium text-gray-800 flex items-center gap-2">
                                              {t.attachments && t.attachments.length > 0 && 
                                                <button onClick={(e) => { e.stopPropagation(); setViewingAttachment(t.attachments![0]); }} title="Ver anexo">
                                                  <Paperclip className="w-4 h-4 text-blue-500 hover:text-blue-700" />
                                                </button>
                                              }
                                              <span>{t.description || getCategoryName(t.categoryId)}</span>
                                            </div>
                                            <div className="text-xs text-gray-500 ml-6">{formatDate(t.date)} - {getCategoryName(t.categoryId)}</div>
                                        </td>
                                        <td className="p-4 text-gray-600 hidden md:table-cell">{getAccountName(t.accountId)}</td>
                                        <td className={`p-4 font-semibold text-right ${t.nature === 'RECEITA' ? 'text-green-600' : 'text-red-600'}`}>{formatCurrency(t.value)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            <PdfOptionsModal
                isOpen={isPdfModalOpen}
                onClose={() => setIsPdfModalOpen(false)}
                onSubmit={handleGeneratePdf}
            />

            <Modal isOpen={isModalOpen} onClose={handleCloseModal} title={transactionToEdit && 'id' in transactionToEdit ? 'Editar Lançamento' : 'Novo Lançamento'}>
                <TransactionForm onSubmit={handleSubmit} onClose={handleCloseModal} transactionToEdit={transactionToEdit} transactionType={transactionType} />
            </Modal>

            {isActionModalOpen && transactionToEdit && (
              <Modal
                isOpen={isActionModalOpen}
                onClose={handleCloseActionModal}
                title="O que deseja fazer?"
              >
                <div className="space-y-4">
                  <p className="text-gray-600 text-center">
                    Lançamento: <span className="font-semibold">{transactionToEdit.description}</span>
                  </p>
                  <div className="flex flex-col gap-3">
                    <button
                      onClick={() => {
                        handleCloseActionModal();
                        handleOpenModal(transactionToEdit as Transaction);
                      }}
                      className="flex items-center justify-center gap-2 w-full px-4 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-semibold shadow transition-colors"
                    >
                      <Edit size={18} />
                      Editar Lançamento
                    </button>
                    <button
                      onClick={() => {
                        handleCloseActionModal();
                        handleDelete(transactionToEdit.id!);
                      }}
                      className="flex items-center justify-center gap-2 w-full px-4 py-3 bg-red-600 text-white rounded-lg hover:bg-red-700 font-semibold shadow transition-colors"
                    >
                      <Trash2 size={18} />
                      Excluir Lançamento
                    </button>
                  </div>
                </div>
              </Modal>
            )}

            <ReceiptScannerModal
                isOpen={isScannerOpen}
                onClose={() => setIsScannerOpen(false)}
                onScanComplete={handleScanComplete}
            />

            <TransactionImportModal
                isOpen={isImportModalOpen}
                onClose={() => setIsImportModalOpen(false)}
                transactionType={transactionType}
            />

            {viewingAttachment && (
              <ViewAttachmentModal
                  isOpen={!!viewingAttachment}
                  onClose={() => setViewingAttachment(null)}
                  attachment={viewingAttachment}
              />
            )}
        </div>
    );
};

export default Transactions;

import React, { createContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { BankAccount, Category, Transaction, Document, Attachment, NewAttachment, KeepAliveLog } from '../types';
import { supabase, base64ToBlob } from '../supabase/client';

interface AppContextType {
  isLoading: boolean;
  accounts: BankAccount[];
  addAccount: (account: Omit<BankAccount, 'id'>) => Promise<BankAccount | null>;
  updateAccount: (account: BankAccount) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  getAccountById: (id: string) => BankAccount | undefined;

  categories: Category[];
  addCategory: (category: Omit<Category, 'id'>) => Promise<void>;
  addCategoriesBatch: (categories: Omit<Category, 'id'>[]) => Promise<void>;
  updateCategory: (category: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;

  transactions: Transaction[];
  addTransaction: (transaction: Omit<Transaction, 'id'>, newAttachments?: NewAttachment[]) => Promise<void>;
  addTransactionsBatch: (transactions: Omit<Transaction, 'id'>[]) => Promise<void>;
  updateTransaction: (transaction: Transaction, newAttachments?: NewAttachment[]) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;

  documents: Document[];
  addDocument: (title: string, fileName: string, base64Data: string) => Promise<void>;
  deleteDocument: (id: string) => Promise<void>;

  keepAliveLogs: KeepAliveLog[];

  calculateCurrentBalance: (accountId: string) => number;
}

export const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [keepAliveLogs, setKeepAliveLogs] = useState<KeepAliveLog[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [accountsRes, categoriesRes, transactionsRes, documentsRes, keepAliveLogsRes] = await Promise.all([
          supabase.from('accounts').select('*'),
          supabase.from('categories').select('*'),
          supabase.from('transactions').select('*').order('date', { ascending: false }),
          supabase.from('documents').select('*').order('created_at', { ascending: false }),
          supabase.from('keep_alive_logs').select('*').order('pinged_at', { ascending: false })
        ]);

        if (accountsRes.error) throw accountsRes.error;
        if (categoriesRes.error) throw categoriesRes.error;
        if (transactionsRes.error) throw transactionsRes.error;
        if (documentsRes.error) throw documentsRes.error;
        if (keepAliveLogsRes.error) throw keepAliveLogsRes.error;

        const typedAccounts = (accountsRes.data || []).map(a => ({...a, dataAbertura: a.dataAbertura.split('T')[0]}));
        const typedTransactions = (transactionsRes.data || []).map(t => ({...t, date: t.date.split('T')[0]}));

        setAccounts(typedAccounts);
        setCategories(categoriesRes.data || []);
        setTransactions(typedTransactions);
        setDocuments(documentsRes.data || []);
        setKeepAliveLogs(keepAliveLogsRes.data || []);

      } catch (error: any)
      {
        console.error("Error fetching initial data:", error.message || error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  // Accounts CRUD
  const addAccount = async (accountData: Omit<BankAccount, 'id'>): Promise<BankAccount | null> => {
    const newAccount = { ...accountData, id: crypto.randomUUID() };
    const { data, error } = await supabase.from('accounts').insert(newAccount).select();
    if (error) {
      console.error("Error adding account:", error);
      return null;
    }
    if (data) {
      const createdAccount = data[0];
      setAccounts(prev => [...prev, createdAccount]);
      return createdAccount;
    }
    return null;
  };
  const updateAccount = async (updatedAccount: BankAccount) => {
    const { error } = await supabase.from('accounts').update(updatedAccount).eq('id', updatedAccount.id);
    if (error) return console.error("Error updating account:", error);
    setAccounts(prev => prev.map(acc => acc.id === updatedAccount.id ? updatedAccount : acc));
  };
  const deleteAccount = async (id: string) => {
    const { error } = await supabase.from('accounts').delete().eq('id', id);
    if (error) return console.error("Error deleting account:", error);
    setAccounts(prev => prev.filter(acc => acc.id !== id));
  };
  const getAccountById = (id: string) => accounts.find(acc => acc.id === id);

  // Categories CRUD
  const addCategory = async (categoryData: Omit<Category, 'id'>) => {
    const newCategory = { ...categoryData, id: crypto.randomUUID() };
    const { error } = await supabase.from('categories').insert(newCategory);
    if (error) return console.error("Error adding category:", error);
    setCategories(prev => [...prev, newCategory]);
  };
  const addCategoriesBatch = async (categoriesData: Omit<Category, 'id'>[]) => {
    const newCategories = categoriesData.map(c => ({ ...c, id: crypto.randomUUID() }));
    const { error } = await supabase.from('categories').insert(newCategories);
    if (error) {
        console.error("Error adding categories in batch:", error);
        throw error;
    }
    setCategories(prev => [...prev, ...newCategories].sort((a, b) => a.name.localeCompare(b.name)));
  };
  const updateCategory = async (updatedCategory: Category) => {
    const { error } = await supabase.from('categories').update(updatedCategory).eq('id', updatedCategory.id);
    if (error) return console.error("Error updating category:", error);
    setCategories(prev => prev.map(cat => cat.id === updatedCategory.id ? updatedCategory : cat));
  };
  const deleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) {
      console.error("Error deleting category:", error.message);
      throw error;
    }
    setCategories(prev => prev.filter(cat => cat.id !== id));
  };

  // Transactions CRUD
  const handleAttachmentUpload = async (newAttachments: NewAttachment[]): Promise<Attachment[]> => {
    const uploadedAttachments: Attachment[] = [];
    for (const attachment of newAttachments) {
      const filePath = `public/${crypto.randomUUID()}-${attachment.name}`;
      const { error: uploadError } = await supabase.storage
        .from('attachments')
        .upload(filePath, base64ToBlob(attachment.data, 'image/jpeg'));

      if (uploadError) {
        console.error('Error uploading attachment:', uploadError);
        continue;
      }

      const { data: { publicUrl } } = supabase.storage.from('attachments').getPublicUrl(filePath);
      uploadedAttachments.push({ id: attachment.id, name: attachment.name, url: publicUrl });
    }
    return uploadedAttachments;
  }

  const addTransaction = async (transactionData: Omit<Transaction, 'id'>, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const newTransaction = { ...transactionData, id: crypto.randomUUID(), attachments: uploadedAttachments };
    const { error } = await supabase.from('transactions').insert(newTransaction);
    if (error) return console.error("Error adding transaction:", error);
    setTransactions(prev => [newTransaction, ...prev].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const addTransactionsBatch = async (transactionsData: Omit<Transaction, 'id'>[]) => {
    const newTransactions = transactionsData.map(t => ({ ...t, id: crypto.randomUUID() }));
    const { error } = await supabase.from('transactions').insert(newTransactions);
    if (error) {
        console.error("Error adding transactions in batch:", error);
        throw error;
    }
    setTransactions(prev => [...prev, ...newTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const updateTransaction = async (updatedTransactionData: Transaction, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const finalAttachments = [...(updatedTransactionData.attachments || []), ...uploadedAttachments];
    const transactionToUpdate = { ...updatedTransactionData, attachments: finalAttachments };
    const { error } = await supabase.from('transactions').update(transactionToUpdate).eq('id', transactionToUpdate.id);
    if (error) return console.error("Error updating transaction:", error);
    setTransactions(prev => prev.map(t => t.id === transactionToUpdate.id ? transactionToUpdate : t).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const deleteTransaction = async (id: string) => {
    const transactionToDelete = transactions.find(t => t.id === id);
    if (transactionToDelete?.attachments) {
      for (const attachment of transactionToDelete.attachments) {
        try {
          const url = new URL(attachment.url);
          const storagePath = url.pathname.split('/attachments/')[1];
          await supabase.storage.from('attachments').remove([storagePath]);
        } catch(e) { console.error("Failed to parse or delete attachment from storage:", e) }
      }
    }
    const { error } = await supabase.from('transactions').delete().eq('id', id);
    if (error) {
        console.error("Error deleting transaction:", error);
        // Lança o erro para que a UI possa reagir (ex: mostrar um alerta)
        throw error;
    }
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  // Documents CRUD
  const addDocument = async (title: string, fileName: string, base64Data: string) => {
      const storagePath = `documents/${crypto.randomUUID()}-${fileName}`;
      const { error: uploadError } = await supabase.storage
          .from('attachments')
          .upload(storagePath, base64ToBlob(base64Data, 'image/jpeg'));
      if (uploadError) return console.error("Error uploading document:", uploadError);

      const newDocument = { title, file_name: fileName, storage_path: storagePath };
      const { data, error } = await supabase.from('documents').insert(newDocument).select();
      if (error) {
        console.error("Error saving document record:", error);
        await supabase.storage.from('attachments').remove([storagePath]);
        return;
      }
      if (data) setDocuments(prev => [data[0], ...prev]);
  };
  const deleteDocument = async (id: string) => {
      const docToDelete = documents.find(d => d.id === id);
      if (!docToDelete) return;

      const { error: storageError } = await supabase.storage.from('attachments').remove([docToDelete.storage_path]);
      if (storageError) console.error("Error deleting document from storage:", storageError);

      const { error: dbError } = await supabase.from('documents').delete().eq('id', id);
      if (dbError) return console.error("Error deleting document from DB:", dbError);

      setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const calculateCurrentBalance = useMemo(() => (accountId: string): number => {
    const account = accounts.find(acc => acc.id === accountId);
    if (!account) return 0;

    const accountTransactions = transactions.filter(t => t.accountId === accountId && t.type === 'checking_account');

    const balance = accountTransactions.reduce((acc, curr) => {
      if (curr.nature === 'RECEITA') {
        return acc + curr.value;
      }
      return acc - curr.value;
    }, 0);

    return balance;
  }, [accounts, transactions]);

  const contextValue = {
    isLoading,
    accounts, addAccount, updateAccount, deleteAccount, getAccountById,
    categories, addCategory, addCategoriesBatch, updateCategory, deleteCategory,
    transactions, addTransaction, addTransactionsBatch, updateTransaction, deleteTransaction,
    documents, addDocument, deleteDocument,
    keepAliveLogs,
    calculateCurrentBalance,
  };

  return (
    <AppContext.Provider value={contextValue}>
      {children}
    </AppContext.Provider>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useAppData } from '../../hooks/useAppData';
import { Transaction, TransactionNature, CategoryType, Attachment, NewAttachment } from '../../types';
import Modal from '../ui/Modal';
import PdfOptionsModal from '../ui/PdfOptionsModal';
import ReceiptScannerModal from '../ai/ReceiptScannerModal';
import TransactionImportModal from '../ui/TransactionImportModal';
import ViewAttachmentModal from '../ui/ViewAttachmentModal';
import CurrencyInput from '../ui/CurrencyInput';
import { formatCurrency, formatDate } from '../../utils/formatters';
import { generateTransactionsPDF } from '../../utils/pdfGenerator';
import { Plus, Trash2, Download, Filter, Wallet, ScanLine, Paperclip, Upload, ArrowRight, Edit } from 'lucide-react';

interface ScannedData {
  value: number;
  date: string;
  description: string;
  scannedImage: string;
}

const TransactionForm: React.FC<{
  onSubmit: (transaction: Omit<Transaction, 'id'>, newAttachments: NewAttachment[]) => Promise<void>;
  onClose: () => void;
  transactionToEdit?: Partial<Transaction> | null;
  transactionType: 'checking_account' | 'credit_card';
}> = ({ onSubmit, onClose, transactionToEdit, transactionType }) => {
    const { accounts, categories } = useAppData();
    const [nature, setNature] = useState<TransactionNature>(transactionToEdit?.nature || TransactionNature.DESPESA);
    const [description, setDescription] = useState(transactionToEdit?.description || '');
    const [accountId, setAccountId] = useState(transactionToEdit?.accountId || '');
    const [categoryId, setCategoryId] = useState(transactionToEdit?.categoryId || '');
    const [date, setDate] = useState(transactionToEdit?.date ? transactionToEdit.date.split('T')[0] : new Date().toISOString().split('T')[0]);
    const [value, setValue] = useState(transactionToEdit?.value || 0);
    const [newAttachment, setNewAttachment] = useState<NewAttachment | null>(null);
    const [errors, setErrors] = useState<{ [key: string]: string }>({});
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [step, setStep] = useState(1);
    const [isDateInputFocused, setIsDateInputFocused] = useState(false);

    const isScannedFlow = useMemo(() => {
      // FIX: Cast to 'unknown' first to resolve unsafe type conversion error.
      return !!(transactionToEdit?.attachments?.[0] as unknown as NewAttachment)?.data;
    }, [transactionToEdit]);

    useEffect(() => {
        setStep(1); // Reset step on modal open/change
        if (transactionToEdit) {
            setNature(transactionToEdit.nature || TransactionNature.DESPESA);
            setDescription(transactionToEdit.description || '');
            setAccountId(transactionToEdit.accountId || '');
            setCategoryId(transactionToEdit.categoryId || '');
            setDate(transactionToEdit.date ? transactionToEdit.date.split('T')[0] : new Date().toISOString().split('T')[0]);
            setValue(transactionToEdit.value || 0);

            // FIX: Cast to 'unknown' first to resolve unsafe type conversion error.
            const potentialNewAttachment = transactionToEdit.attachments?.[0] as unknown as NewAttachment | undefined;
            setNewAttachment(potentialNewAttachment?.data ? potentialNewAttachment : null);

        } else { // Reset for new manual transaction
            setNature(TransactionNature.DESPESA);
            setDescription('');
            setAccountId('');
            setCategoryId('');
            setDate(new Date().toISOString().split('T')[0]);
            setValue(0);
            setNewAttachment(null);
        }
    }, [transactionToEdit]);

    const filteredCategories = useMemo(() => {
        return categories.filter(c => c.type === (nature as unknown as CategoryType));
    }, [categories, nature]);

    const validate = () => {
        const newErrors: { [key: string]: string } = {};
        if (!accountId) newErrors.accountId = 'Selecione uma conta.';
        if (!categoryId) newErrors.categoryId = 'Selecione uma categoria.';
        if (value <= 0) newErrors.value = 'O valor deve ser maior que zero.';
        if (!date) newErrors.date = 'A data é obrigatória.';
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleNext = (e: React.MouseEvent<HTMLButtonElement>) => {
        e.preventDefault();
        if (validate()) {
            setStep(2);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validate()) return;
        setIsSubmitting(true);
        const transactionData = { description, nature, accountId, categoryId, date, value, type: transactionType };
        await onSubmit(transactionData, newAttachment ? [newAttachment] : []);
        setIsSubmitting(false);
    };

    const formFields = (
      <div className="space-y-3">
        <div>
            <label className="block text-sm font-medium text-gray-600 mb-2">Natureza do Lançamento</label>
            <div className="grid grid-cols-2 gap-4">
                <button type="button" onClick={() => { setNature(TransactionNature.RECEITA); setCategoryId(''); }} className={`p-2 rounded-lg font-semibold transition ${nature === TransactionNature.RECEITA ? 'bg-green-500 text-white ring-2 ring-green-600 ring-offset-2' : 'bg-gray-100 hover:bg-green-100'}`}>Receita</button>
                <button type="button" onClick={() => { setNature(TransactionNature.DESPESA); setCategoryId(''); }} className={`p-2 rounded-lg font-semibold transition ${nature === TransactionNature.DESPESA ? 'bg-red-500 text-white ring-2 ring-red-600 ring-offset-2' : 'bg-gray-100 hover:bg-red-100'}`}>Despesa</button>
            </div>
        </div>

        <div>
            <label htmlFor="description" className="block text-sm font-medium text-gray-600">Descrição</label>
            <input
                type="text"
                id="description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="mt-1 w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Ex: Compras do mês"
            />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
                <label htmlFor="accountId" className="block text-sm font-medium text-gray-600">Conta Bancária</label>
                <select id="accountId" value={accountId} onChange={(e) => setAccountId(e.target.value)} className={`mt-1 w-full px-3 py-2 border ${errors.accountId ? 'border-red-500' : 'border-gray-300'} bg-white rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}>
                    <option value="">Selecione...</option>
                    {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                </select>
            </div>
            <div>
                <label htmlFor="categoryId" className="block text-sm font-medium text-gray-600">Categoria</label>
                <select id="categoryId" value={categoryId} onChange={(e) => setCategoryId(e.target.value)} className={`mt-1 w-full px-3 py-2 border ${errors.categoryId ? 'border-red-500' : 'border-gray-300'} bg-white rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}>
                    <option value="">Selecione...</option>
                    {filteredCategories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>
            </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
                <label htmlFor="date" className="block text-sm font-medium text-gray-600">Data</label>
                <input
                    type={isDateInputFocused ? 'date' : 'text'}
                    id="date"
                    value={isDateInputFocused ? date : (date ? formatDate(date) : '')}
                    onFocus={() => setIsDateInputFocused(true)}
                    onBlur={() => setIsDateInputFocused(false)}
                    onChange={(e) => setDate(e.target.value)}
                    className={`mt-1 w-full px-3 py-2 border ${errors.date ? 'border-red-500' : 'border-gray-300'} rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500`}
                />
            </div>
            <div>
                <label htmlFor="value" className="block text-sm font-medium text-gray-600">Valor</label>
                <CurrencyInput id="value" value={value} onChange={setValue} />
                {errors.value && <p className="text-sm text-red-500 mt-1">{errors.value}</p>}
            </div>
        </div>
      </div>
    );

    return (
        <form onSubmit={handleSubmit}>
            {isScannedFlow ? (
                // Multi-step flow for scanned receipts
                <div className="space-y-4">
                    {step === 1 && (
                        formFields
                    )}
                    {step === 2 && (
                         <div className="space-y-4">
                            <p className="text-center text-gray-600">Por favor, confirme o anexo para salvar.</p>
                            {newAttachment && (
                                <div className="relative group">
                                    <p className="text-sm font-medium text-gray-600 mb-1">Recibo Digitalizado</p>
                                    <img
                                        src={`data:image/jpeg;base64,${newAttachment.data}`}
                                        alt="Recibo digitalizado"
                                        className="rounded-lg border p-1 max-h-60 w-auto mx-auto"
                                    />
                                </div>
                            )}
                        </div>
                    )}
                </div>
            ) : (
                // Single-step for manual entry/edit
                formFields
            )}

            <div className="flex justify-end gap-3 pt-4 mt-4 border-t border-gray-100">
                {isScannedFlow && step === 2 && (
                    <button type="button" onClick={() => setStep(1)} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors">Voltar</button>
                )}
                <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors">Cancelar</button>
                {isScannedFlow && step === 1 ? (
                    <button type="button" onClick={handleNext} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors font-semibold shadow">
                        Próximo <ArrowRight size={16} />
                    </button>
                ) : (
                    <button type="submit" disabled={isSubmitting} className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors font-semibold shadow disabled:bg-blue-300">
                        {isSubmitting ? 'Salvando...' : 'Confirmar'}
                    </button>
                )}
            </div>
        </form>
    );
};


const Transactions: React.FC<{ transactionType: 'checking_account' | 'credit_card', title: string }> = ({ transactionType, title }) => {
    const { transactions, categories, accounts, addTransaction, updateTransaction, deleteTransaction, getAccountById } = useAppData();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isActionModalOpen, setIsActionModalOpen] = useState(false);
    const [isPdfModalOpen, setIsPdfModalOpen] = useState(false);
    const [isScannerOpen, setIsScannerOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [transactionToEdit, setTransactionToEdit] = useState<Partial<Transaction> | null>(null);
    const [viewingAttachment, setViewingAttachment] = useState<Attachment | null>(null);

    const [filterDate, setFilterDate] = useState('');
    const [filterCategory, setFilterCategory] = useState('');
    const [filterNature, setFilterNature] = useState('');

    const filteredTransactions = useMemo(() => {
        return transactions
            .filter(t => t.type === transactionType)
            .filter(t => !filterDate || t.date.startsWith(filterDate))
            .filter(t => !filterCategory || t.categoryId === filterCategory)
            .filter(t => !filterNature || t.nature === filterNature);
    }, [transactions, transactionType, filterDate, filterCategory, filterNature]);

    const handleOpenModal = (transaction?: Transaction) => {
        setTransactionToEdit(transaction || null);
        setIsModalOpen(true);
    };

    const handleRowClick = (transaction: Transaction) => {
        setTransactionToEdit(transaction);
        setIsActionModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setTransactionToEdit(null);
    };

    const handleCloseActionModal = () => {
        setIsActionModalOpen(false);
        setTransactionToEdit(null);
    };

    const handleSubmit = async (data: Omit<Transaction, 'id'>, newAttachments: NewAttachment[]) => {
        if (transactionToEdit && 'id' in transactionToEdit) {
            await updateTransaction({ ...transactionToEdit, ...data } as Transaction, newAttachments);
        } else {
            await addTransaction(data, newAttachments);
        }
        handleCloseModal();
    };

    const handleDelete = async (id: string) => {
        // A confirmação do usuário agora é feita através do modal de ação (Editar/Excluir).
        // Removemos o `window.confirm` para uma experiência de usuário mais fluida e adicionamos tratamento de erro.
        try {
            await deleteTransaction(id);
        } catch (error) {
            console.error("Falha ao excluir a transação:", error);
            alert("Não foi possível excluir a transação. Verifique o console para mais detalhes.");
        }
    };

    const handleGeneratePdf = ({ accountId, startDate, endDate }: { accountId: string, startDate: string, endDate: string }) => {
        const account = getAccountById(accountId);
        if (!account) return;

        const start = new Date(startDate);
        const end = new Date(endDate);
        start.setUTCHours(0,0,0,0);
        end.setUTCHours(23,59,59,999);

        const transactionsInPeriod = transactions.filter(t => {
            const tDate = new Date(t.date);
            return t.accountId === accountId && tDate >= start && tDate <= end && t.type === transactionType;
        });

        generateTransactionsPDF({
            account,
            period: { start: startDate, end: endDate },
            transactionsInPeriod,
            allTransactions: transactions,
            transactionType,
            title
        });
        setIsPdfModalOpen(false);
    };

    const handleScanComplete = (data: ScannedData) => {
      const newAttachment: NewAttachment = {
        id: crypto.randomUUID(),
        name: `Recibo_${data.date}.jpg`,
        type: 'image_base64_jpeg',
        data: data.scannedImage,
      };

      const despesaCategory = categories.find(c => c.type === CategoryType.DESPESA);

      setTransactionToEdit({
        description: data.description,
        value: data.value,
        date: data.date,
        nature: TransactionNature.DESPESA,
        categoryId: despesaCategory?.id || '',
        attachments: [newAttachment] as any, // Transient state
      });
      setIsScannerOpen(false);
      setIsModalOpen(true);
    };

    const getCategoryName = (id: string) => categories.find(c => c.id === id)?.name || 'N/A';
    const getAccountName = (id: string) => accounts.find(a => a.id === id)?.name || 'N/A';

    return (
         <div className="space-y-8">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800">{title}</h1>
                    <p className="text-gray-500 mt-1">Registre e gerencie suas movimentações financeiras.</p>
                </div>
                <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
                    {transactionType === 'credit_card' && (
                        <button onClick={() => setIsImportModalOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors font-semibold shadow-sm">
                            <Upload size={18} />
                            Importar XLS
                        </button>
                    )}
                    <button onClick={() => setIsPdfModalOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-100 transition-colors font-semibold shadow-sm">
                        <Download size={18} />
                        Gerar PDF
                    </button>
                    <button onClick={() => setIsScannerOpen(true)} className="flex items-center justify-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-semibold shadow">
                        <ScanLine size={20} />
                        Digitalizar com IA
                    </button>
                    <button onClick={() => handleOpenModal()} className="flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-semibold shadow">
                        <Plus size={20} />
                        Lançamento
                    </button>
                </div>
            </div>

            <div className="bg-white p-4 rounded-2xl shadow-sm">
                <div className="flex items-center gap-2 mb-4">
                    <Filter size={18} className="text-gray-500" />
                    <h3 className="font-semibold text-gray-600">Filtros</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                    <input type="date" value={filterDate} onChange={e => setFilterDate(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300" />
                    <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <option value="">Todas as categorias</option>
                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                    <select value={filterNature} onChange={e => setFilterNature(e.target.value)} className="w-full px-3 py-2 border border-gray-200 bg-gray-50 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300">
                        <option value="">Toda natureza</option>
                        <option value="RECEITA">Receita</option>
                        <option value="DESPESA">Despesa</option>
                    </select>
                </div>
            </div>

            <div className="bg-white p-4 sm:p-6 rounded-2xl shadow-sm">
                {filteredTransactions.length === 0 ? (
                    <div className="text-center py-16">
                        <Wallet className="mx-auto h-12 w-12 text-gray-300" />
                        <p className="text-gray-500 mt-4">Nenhum lançamento encontrado.</p>
                        <p className="text-gray-400 text-sm mt-1">{transactions.length > 0 ? "Ajuste os filtros ou adicione um novo lançamento." : 'Clique em "Criar Lançamento" para começar.'}</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="border-b-2 border-gray-100">
                                <tr>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider">Descrição</th>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider hidden md:table-cell">Conta</th>
                                    <th className="p-4 text-sm font-semibold text-gray-500 uppercase tracking-wider text-right">Valor</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredTransactions.map(t => (
                                    <tr key={t.id} onClick={() => handleRowClick(t)} className="border-b border-gray-100 last:border-b-0 hover:bg-gray-50/50 transition-colors cursor-pointer">
                                        <td className="p-4">
                                            <div className="font-medium text-gray-800 flex items-center gap-2">
                                              {t.attachments && t.attachments.length > 0 && 
                                                <button onClick={(e) => { e.stopPropagation(); setViewingAttachment(t.attachments![0]); }} title="Ver anexo">
                                                  <Paperclip className="w-4 h-4 text-blue-500 hover:text-blue-700" />
                                                </button>
                                              }
                                              <span>{t.description || getCategoryName(t.categoryId)}</span>
                                            </div>
                                            <div className="text-xs text-gray-500 ml-6">{formatDate(t.date)} - {getCategoryName(t.categoryId)}</div>
                                        </td>
                                        <td className="p-4 text-gray-600 hidden md:table-cell">{getAccountName(t.accountId)}</td>
                                        <td className={`p-4 font-semibold text-right ${t.nature === 'RECEITA' ? 'text-green-600' : 'text-red-600'}`}>{formatCurrency(t.value)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            <PdfOptionsModal
                isOpen={isPdfModalOpen}
                onClose={() => setIsPdfModalOpen(false)}
                onSubmit={handleGeneratePdf}
            />

            <Modal isOpen={isModalOpen} onClose={handleCloseModal} title={transactionToEdit && 'id' in transactionToEdit ? 'Editar Lançamento' : 'Novo Lançamento'}>
                <TransactionForm onSubmit={handleSubmit} onClose={handleCloseModal} transactionToEdit={transactionToEdit} transactionType={transactionType} />
            </Modal>

            {isActionModalOpen && transactionToEdit && (
              <Modal
                isOpen={isActionModalOpen}
                onClose={handleCloseActionModal}
                title="O que deseja fazer?"
              >
                <div className="space-y-4">
                  <p className="text-gray-600 text-center">
                    Lançamento: <span className="font-semibold">{transactionToEdit.description}</span>
                  </p>
                  <div className="flex flex-col gap-3">
                    <button
                      onClick={() => {
                        handleCloseActionModal();
                        handleOpenModal(transactionToEdit as Transaction);
                      }}
                      className="flex items-center justify-center gap-2 w-full px-4 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-semibold shadow transition-colors"
                    >
                      <Edit size={18} />
                      Editar Lançamento
                    </button>
                    <button
                      onClick={() => {
                        handleCloseActionModal();
                        if (transactionToEdit.id) handleDelete(transactionToEdit.id);
                      }}
                      className="flex items-center justify-center gap-2 w-full px-4 py-3 bg-red-600 text-white rounded-lg hover:bg-red-700 font-semibold shadow transition-colors"
                    >
                      <Trash2 size={18} />
                      Excluir Lançamento
                    </button>
                  </div>
                </div>
              </Modal>
            )}

            <ReceiptScannerModal
                isOpen={isScannerOpen}
                onClose={() => setIsScannerOpen(false)}
                onScanComplete={handleScanComplete}
            />

            <TransactionImportModal
                isOpen={isImportModalOpen}
                onClose={() => setIsImportModalOpen(false)}
                transactionType={transactionType}
            />

            {viewingAttachment && (
              <ViewAttachmentModal
                  isOpen={!!viewingAttachment}
                  onClose={() => setViewingAttachment(null)}
                  attachment={viewingAttachment}
              />
            )}
        </div>
    );
};

export default Transactions;
